VALUE = CONFIG["value_column"]
RESERVED = {"by", "period", "previous", "level", "parent", "threshold", "max_items", "relative_to",
            "adjust", "start", "end", "group", "limit", "thresholds", "geometry", "envelope", "base",
            # parameters of the endpoints for agents (trend, trends, forecast, events, flows)
            "method", "horizon", "interval", "aggregate", "backtest", "from", "to", "category", "kind",
            "measure", "depth"}
LADDER = [0.1, 0.01, 0.001, 0.0001, 0.00001]
FOCUS = CONFIG.get("focus") or {}
# What a query uses for a dimension it does not filter: the focus (e.g. reporter=LU), else the
# dimension's default (its total, or the headline unit), so values are never double counted.
DEFAULTS = {**CONFIG["defaults"], **FOCUS}
SDMX = CONFIG.get("sdmx")                     # live source for slices that were never loaded
UNIT_MULT = CONFIG.get("unit_mult_column")    # SDMX UNIT_MULT attribute: values are x 10^n
CODE_LABELS = CONFIG.get("code_labels") or {}
REGISTRY = "_loaded_slice"
NOT_APPLICABLE = {"_Z", "_X", "_N", "_U"}     # SDMX "not applicable / not available" codes
_PARENT_CODES: dict[str, set] = {}
# enum literal -> SDMX code, per dimension
_CODE_OF = {d["id"]: {lit: code for code, lit in d["literals"].items()} for d in CONFIG["dimensions"]
            if d["kind"] == "enum"}


def _value_expr(alias: str = "o") -> str:
    """The observed value in real units: SDMX UNIT_MULT=6 means 'in millions'."""
    v = f'{alias}."{VALUE}"'
    if not UNIT_MULT:
        return v
    cases = " ".join(f"WHEN '{k}' THEN 1e{k}" for k in range(-6, 13))
    return f'({v} * (CASE {alias}."{UNIT_MULT}" {cases} ELSE 1 END))'


VALUE_EXPR = _value_expr()


# --------------------------------------------------------------------------- helpers
def _dim(dim_id: str) -> dict:
    if dim_id not in DIMS:
        raise HTTPException(400, f"Unknown dimension {dim_id!r}; known: {sorted(DIMS)}")
    return DIMS[dim_id]


def _normalise(dim: dict, value: str) -> str:
    """Accept SDMX codes or enum literal names for enumerated dimensions."""
    if dim["kind"] == "enum":
        return dim["literals"].get(value, value)
    return value


_KNOWN: dict[str, set] = {}


def _known_codes(db: Session, dim: dict) -> set:
    if dim["id"] not in _KNOWN:
        if dim["kind"] == "enum":
            _KNOWN[dim["id"]] = set(dim["literals"].values())
        elif dim["kind"] == "class":
            _KNOWN[dim["id"]] = {r[0] for r in db.execute(text(f'SELECT code FROM "{dim["table"]}"')).fetchall()}
        else:
            return set()
    return _KNOWN[dim["id"]]


def _check(db: Session, dim: dict, values: list[str]) -> None:
    """Unknown codes are a 400, not an empty answer that looks like 'no trade'."""
    if dim["kind"] not in ("enum", "class"):
        return
    known = _known_codes(db, dim)
    bad = [v for v in values if v not in known]
    if bad:
        raise HTTPException(400, f"Unknown code(s) {bad} for dimension {dim['id']!r}")


def _filters(request: Request, exclude: set[str], db: Optional[Session] = None) -> dict[str, list[str]]:
    """Dimension filters from the query string, completed with the configured defaults."""
    out: dict[str, list[str]] = {}
    for key, raw in request.query_params.items():
        if key in RESERVED or key not in DIMS:
            continue
        if key in exclude:
            # Not applied (the endpoint groups by it), but a typo still answers 400, not 200.
            if db is not None:
                _check(db, DIMS[key], [_normalise(DIMS[key], v) for v in raw.split(",") if v != ""])
            continue
        out[key] = [_normalise(DIMS[key], v) for v in raw.split(",") if v != ""]
        if db is not None:
            _check(db, DIMS[key], out[key])
    # A month (2020-03) asked without a frequency means the monthly data, not the annual default.
    freq = CONFIG.get("frequency_dimension")
    if freq and freq not in out and freq not in exclude and freq not in request.query_params:
        sub = _frequency_of_periods(request)
        if sub:
            out[freq] = [_normalise(DIMS[freq], sub)]
    for dim_id, default in DEFAULTS.items():
        if dim_id not in out and dim_id not in exclude and default is not None:
            values = default if isinstance(default, list) else [default]
            out[dim_id] = [_normalise(DIMS[dim_id], v) for v in values]
    return out


_SUB_ANNUAL = (("M", re.compile(r"\d{4}-(0[1-9]|1[0-2])")), ("Q", re.compile(r"\d{4}-Q[1-4]")),
               ("S", re.compile(r"\d{4}-S[12]")))


def _frequency_of_periods(request: Request) -> Optional[str]:
    """M, Q or S when the request's periods (period, previous, start, end, base) are months,
    quarters or semesters; None for years (the default frequency)."""
    for key in ("period", "previous", "start", "end", "base"):
        value = request.query_params.get(key) or ""
        for freq, pattern in _SUB_ANNUAL:
            if pattern.fullmatch(value):
                return freq
    return None


def _where(filters: dict[str, list[str]], params: dict, alias: str = "o") -> list[str]:
    clauses = []
    for i, (dim_id, values) in enumerate(filters.items()):
        col = DIMS[dim_id]["column"]
        names = []
        for j, v in enumerate(values):
            p = f"f{i}_{j}"
            params[p] = v
            names.append(f":{p}")
        clauses.append(f'{alias}."{col}" IN ({", ".join(names)})')
    return clauses


def _clean(label: str) -> str:
    """Readable labels: drop Eurostat's historical notes "(incl. ...)" and un-shout ALL-CAPS names."""
    label = label.replace(" ", " ")
    cut = label.find(" (incl.")
    if cut > 0:
        label = label[:cut]
    letters = [c for c in label if c.isalpha()]
    if letters and sum(c.isupper() for c in letters) / len(letters) > 0.8:
        label = label[:1].upper() + label[1:].lower()
    return re.sub(r"\s+", " ", label).strip()


def _enum_label(dim: dict, literal: str) -> str:
    """Codelist name of an enum value (Imports, Exports...), else a readable form of the literal."""
    code = _CODE_OF.get(dim["id"], {}).get(literal, literal)
    name = CODE_LABELS.get(dim["id"], {}).get(code) or literal
    if " " not in name:  # a code-like name (VALUE_IN_EUROS): make it readable
        name = name.replace("_", " ").lower().capitalize()
    return _clean(name)


def _labels(db: Session, dim: dict, codes: list[str]) -> dict[str, str]:
    if dim["kind"] == "enum":
        return {c: _enum_label(dim, c) for c in codes}
    if dim["kind"] != "class" or not codes:
        return {c: c for c in codes}
    params = {f"c{i}": c for i, c in enumerate(codes)}
    rows = db.execute(text(f'SELECT code, label FROM "{dim["table"]}" WHERE code IN ({", ".join(":" + k for k in params)})'),
                      params).fetchall()
    found = {r[0]: _clean(r[1] or r[0]) for r in rows}
    return {c: found.get(c, c) for c in codes}


def _level_of(db: Session, dim: dict, code: str) -> int:
    row = db.execute(text(f'SELECT level FROM "{dim["table"]}" WHERE code = :c'), {"c": code}).fetchone()
    return int(row[0]) if row and row[0] is not None else 0


def _is_member(dim: dict, code: str, db: Optional[Session] = None) -> bool:
    """A "real" item of a dimension: not its total, matching its member pattern (countries, not
    aggregates) and, for a geographic hierarchy, a leaf (DE, not EU27)."""
    pattern = dim.get("member_pattern")
    total = dim.get("total_code")
    if total and code == total:
        return False
    if pattern and not re.fullmatch(pattern, code):
        return False
    if db is not None and dim.get("role") == "geo" and dim.get("hierarchy"):
        if dim["id"] not in _PARENT_CODES:
            rows = db.execute(text(f'SELECT DISTINCT "{dim["parent_column"]}" FROM "{dim["table"]}"')).fetchall()
            _PARENT_CODES[dim["id"]] = {r[0] for r in rows if r[0]}
        return code not in _PARENT_CODES[dim["id"]]
    return True


def _in_view(dim: dict, code: str, db: Session, parent: Optional[str]) -> bool:
    """Items shown for a dimension: its members, or, when drilling into ``parent``, its children."""
    if parent and dim.get("hierarchy"):
        return code != parent
    return _is_member(dim, code, db)


def _drill_level(db: Session, dim: dict, level: Optional[int], parent: Optional[str]) -> Optional[int]:
    """Level to rank at: the children of ``parent``; for a nomenclature without parent, its first
    level below the total. Geographic dimensions rank their member countries instead."""
    if not dim.get("hierarchy"):
        return None
    if level is not None:
        return level
    if parent:
        return _level_of(db, dim, parent) + 1
    if dim.get("role") == "geo":
        return None
    return 1 if dim.get("total_code") else 0


def _grouped(db: Session, by: dict, filters: dict, level: Optional[int], parent: Optional[str]) -> dict[str, float]:
    params: dict = {}
    where = _where(filters, params)
    join = ""
    if by.get("hierarchy"):
        join = f'JOIN "{by["table"]}" d ON d.code = o."{by["column"]}"'
        if level is not None:
            where.append("d.level = :lvl")
            params["lvl"] = level
        if parent and parent == by.get("total_code"):
            pass   # every code at that level sits under the total
        elif parent and level is not None and by.get("role") != "geo" and level > _level_of(db, by, parent) + 1:
            # descendants two or more levels down (7216 -> 72163390): a product code starts with its ancestors'
            where.append("d.code LIKE :prefix AND d.code <> :parent")
            params["prefix"], params["parent"] = parent + "%", parent
        elif parent:
            where.append(f'd."{by["parent_column"]}" = :parent')
            params["parent"] = parent
    sql = (f'SELECT o."{by["column"]}" AS code, SUM({VALUE_EXPR}) AS value FROM "{OBS}" o {join} '
           f'WHERE {" AND ".join(where) if where else "1=1"} GROUP BY o."{by["column"]}"')
    return {r[0]: float(r[1] or 0) for r in db.execute(text(sql), params).fetchall()}


def _value_of(db: Session, by: dict, code: str, filters: dict) -> Optional[float]:
    params: dict = {"code": code}
    where = _where(filters, params) + [f'o."{by["column"]}" = :code']
    row = db.execute(text(f'SELECT SUM({VALUE_EXPR}) FROM "{OBS}" o WHERE {" AND ".join(where)}'), params).fetchone()
    return float(row[0]) if row and row[0] is not None else None


def _default_threshold(by: dict, level: Optional[int]) -> float:
    """The significance ladder: one decimal less per level of detail."""
    base = CONFIG["base_threshold"]
    if by.get("hierarchy") and by.get("role") != "geo" and level:
        return base / (10 ** (level - 1))
    return base


def _previous(period: str) -> str:
    """The period before ``period`` (2025 -> 2024, 2025-03 -> 2025-02)."""
    if re.fullmatch(r"\d{4}", period):
        return str(int(period) - 1)
    m = re.fullmatch(r"(\d{4})-(\d{2})", period)
    if m:
        y, mo = int(m.group(1)), int(m.group(2))
        return f"{y - 1}-12" if mo == 1 else f"{y}-{mo - 1:02d}"
    return period


# --------------------------------------------------------------------------- live fetch
# A query "needs" a slice: per dimension, ("all", None) = every code, ("all_of", codes) = these
# codes, ("any_of", codes) = some of these (the children of a drilled item). The registry says
# which slices the loader (or an earlier live fetch) put in the database; anything else is
# fetched from the SDMX source, stored, and registered.
_LOCK = threading.Lock()
_FAILED: dict[str, float] = {}
_REGISTRY_CACHE: list = []
RETRY_AFTER = 120  # seconds before a failed live fetch is tried again


def _registry(db: Session) -> list[tuple[dict, Optional[str], Optional[str], str]]:
    if not _REGISTRY_CACHE:
        try:
            rows = db.execute(text(f'SELECT spec, start_period, end_period, source FROM "{REGISTRY}"')).fetchall()
        except Exception:  # database loaded before the registry existed
            db.rollback()
            rows = []
        _REGISTRY_CACHE.append([(json.loads(s), a, b, src) for s, a, b, src in rows])
    return _REGISTRY_CACHE[0]


def _sdmx_codes(dim: dict, values) -> set:
    rev = _CODE_OF.get(dim["id"], {})
    return {rev.get(v, v) for v in values}


def _needed(db: Session, filters: dict, by: Optional[dict] = None, parent: Optional[str] = None,
            level: Optional[int] = None) -> tuple[dict, dict]:
    """(needed slice, extra codes to fetch) for a query: its filters, plus what ``by`` ranks."""
    needed: dict = {}
    extra: dict = {}
    for dim_id, values in filters.items():
        d = DIMS[dim_id]
        if d.get("role") == "time":
            continue
        needed[dim_id] = ("all_of", _sdmx_codes(d, values))
    if by is not None:
        if by.get("hierarchy") and parent:
            kids = {r[0] for r in db.execute(text(f'SELECT code FROM "{by["table"]}" WHERE "{by["parent_column"]}" = :p'),
                                             {"p": parent}).fetchall()}
            needed[by["id"]] = ("any_of", kids) if kids else ("all_of", {parent})
            extra[by["id"]] = {parent}  # its total, for shares and coverage
        elif by.get("hierarchy") and level is not None:
            codes = {r[0] for r in db.execute(text(f'SELECT code FROM "{by["table"]}" WHERE level = :l'),
                                              {"l": level}).fetchall()}
            needed[by["id"]] = ("any_of", codes) if codes else ("all", None)
            if by.get("total_code"):
                extra[by["id"]] = {by["total_code"]}
        else:
            needed[by["id"]] = ("all", None)
    return needed, extra


def _in_range(start: Optional[str], end: Optional[str], a: Optional[str], b: Optional[str]) -> bool:
    if a and start and start[:len(a)] < a:
        return False
    if b and end and end[:len(b)] > b:
        return False
    return True


def _covered(db: Session, needed: dict, start: Optional[str], end: Optional[str]) -> Optional[bool]:
    """True/False from the registry; None when the database has no registry (loaded before it existed)."""
    reg = _registry(db)
    if not any(src == "load" for _, _, _, src in reg):
        return None
    for spec, a, b, _ in reg:
        if not _in_range(start, end, a, b):
            continue
        ok = True
        for dim_id, (mode, codes) in needed.items():
            have = spec.get(dim_id, "*")
            if have == "*":
                continue
            have = set(have)
            if mode == "all" or (mode == "all_of" and not codes <= have) or (mode == "any_of" and not codes & have):
                ok = False
                break
        if ok:
            return True
    return False


def _sdmx_key(needed: dict, extra: dict) -> str:
    parts = []
    for dim_id in SDMX["dimensions"]:
        mode, codes = needed.get(dim_id, ("all", None))
        if mode == "all":
            parts.append("")
        else:
            parts.append("+".join(sorted(set(codes) | extra.get(dim_id, set()))))
    return ".".join(parts)


def _fetch_and_store(db: Session, key: str, needed: dict, extra: dict, start: Optional[str], end: Optional[str]) -> int:
    import requests  # only needed for live fetches

    url = f'{SDMX["base_url"]}/data/{SDMX["flow"]}/{key}'
    params = {k: v for k, v in (("startPeriod", start), ("endPeriod", end)) if v}
    r = requests.get(url, params=params, timeout=SDMX.get("timeout", 20),
                     headers={"Accept": "application/vnd.sdmx.data+csv;version=1.0.0",
                              "User-Agent": "besser-sdmx insights (live fetch)"})
    body = "" if r.status_code == 404 else r.text  # SDMX 404 = no results
    if r.status_code not in (200, 404):
        r.raise_for_status()
    if body.lstrip().startswith("<"):
        raise RuntimeError("the provider answered XML instead of data (query too large or error)")
    records = list(csv.DictReader(io.StringIO(body))) if body.strip() else []
    if records:
        lower = {c.lower(): c for c in records[0]}
        dims = [d for d in CONFIG["dimensions"] if d.get("role") != "time"]
        src = {d["id"]: lower.get(d["id"].lower()) for d in dims}
        missing = [d for d, c in src.items() if c is None]
        if missing:
            raise RuntimeError(f"columns {missing} not in the provider's data")
        attrs = {col: lower.get(sid.lower()) for sid, col in (SDMX.get("attributes") or {}).items()}
        rows, unknown = [], {}
        for rec in records:
            row = {}
            skip = False
            for d in dims:
                code = rec[src[d["id"]]]
                if d["kind"] == "enum":
                    lit = d["literals"].get(code)
                    if lit is None:
                        skip = True
                        break
                    row[d["column"]] = lit
                else:
                    row[d["column"]] = code
                    if d["kind"] == "class" and code not in _known_codes(db, d):
                        unknown.setdefault(d["id"], set()).add(code)
            if skip:
                continue
            row[TIME] = rec[lower["time_period"]]
            raw = rec.get(lower.get("obs_value", ""), "")
            row[VALUE] = float(raw) if raw not in ("", None) else None
            for col, c in attrs.items():
                row[col] = (rec.get(c) or None) if c else None
            rows.append(row)
        for dim_id, codes in unknown.items():  # e.g. product codes newer than the codelist
            d = DIMS[dim_id]
            cols = "code, label" + (", level" if d.get("hierarchy") else "")
            vals = ":c, :c" + (", 0" if d.get("hierarchy") else "")
            db.execute(text(f'INSERT INTO "{d["table"]}" ({cols}) VALUES ({vals})'), [{"c": c} for c in sorted(codes)])
            _known_codes(db, d).update(codes)
        if rows:
            keys = [d["column"] for d in dims] + [TIME]
            cond = " AND ".join(f'"{k}" = :{k}' for k in keys)
            db.execute(text(f'DELETE FROM "{OBS}" WHERE {cond}'), [{k: r[k] for k in keys} for r in rows])
            cols = list(rows[0])
            db.execute(text(f'INSERT INTO "{OBS}" ({", ".join(chr(34) + c + chr(34) for c in cols)}) '
                            f'VALUES ({", ".join(":" + c for c in cols)})'), rows)
    spec = {dim_id: ("*" if mode == "all" else sorted(set(codes) | extra.get(dim_id, set())))
            for dim_id, (mode, codes) in needed.items()}
    db.execute(text(f'CREATE TABLE IF NOT EXISTS "{REGISTRY}" (id INTEGER PRIMARY KEY AUTOINCREMENT, '
                    'spec TEXT NOT NULL, start_period TEXT, end_period TEXT, rows INTEGER, source TEXT, loaded_at TEXT)'))
    db.execute(text(f'INSERT INTO "{REGISTRY}" (spec, start_period, end_period, rows, source, loaded_at) '
                    'VALUES (:spec, :start, :end, :rows, :source, :at)'),
               {"spec": json.dumps(spec, sort_keys=True), "start": start, "end": end, "rows": len(records),
                "source": "live", "at": datetime.now(timezone.utc).isoformat(timespec="seconds")})
    db.commit()
    _REGISTRY_CACHE.clear()
    return len(records)


def _ensure(db: Session, needed: dict, extra: dict, start: Optional[str], end: Optional[str],
            probe: Callable[[], bool]) -> dict:
    """Make sure the slice a query needs is in the database; fetch it live if it never was.

    Returns flags for the response: ``fetched_live`` (it came from the source during this request)
    and ``loaded`` (False: not in the database and the source could not be reached).
    """
    status = {"fetched_live": False, "loaded": True}
    if not SDMX:
        return status
    covered = _covered(db, needed, start, end)
    if covered is None:  # no registry: whatever is in the database counts as loaded
        covered = probe()
    if covered:
        return status
    key = _sdmx_key(needed, extra)
    tag = f"{key}|{start}|{end}"
    with _LOCK:
        if _covered(db, needed, start, end):  # fetched by a concurrent request meanwhile: re-query
            return {"fetched_live": True, "loaded": True, "source": SDMX.get("name")}
        if time.time() - _FAILED.get(tag, 0) < RETRY_AFTER:
            return {**status, "loaded": False}
        try:
            rows = _fetch_and_store(db, key, needed, extra, start, end)
        except Exception as exc:  # offline, timeout, provider error: say so, never show zeros
            db.rollback()
            _FAILED[tag] = time.time()
            return {**status, "loaded": False, "error": str(exc)[:200]}
    return {"fetched_live": True, "loaded": True, "fetched_rows": rows, "source": SDMX.get("name")}


def _window(period: str, previous: Optional[str] = None) -> tuple[str, str]:
    """The span of two compared periods, in order."""
    a, b = sorted((previous or _previous(period), period))
    return a, b


# --------------------------------------------------------------------------- measures (value, weight, units)
# ds-045409 publishes three indicators (its content constraint): VALUE_IN_EUROS, QUANTITY_IN_100KG (net mass)
# and SUPPLEMENTARY_QUANTITY (a CN8 line's own unit: number of items, litres, pairs...; only CN8 lines have
# one). Every endpoint reads euros unless asked otherwise with ``measure``: value (euros, the default), weight
# (tonnes: 100 kg x 0.1), units (the supplementary unit, named from Comext's CN8-SUPPL_UNIT file: see
# scripts/suppl_units.py; a heading or HS6 line sums its CN8 lines when they all count in one unit) or all
# (every measure of each row, with the unit values in euros per tonne and per unit). Quantities are fetched
# live on first use like any slice; a line without a published quantity says so, never 0.
MEASURES = ("value", "weight", "units", "all")
IND_DIM = "indicators"
IND_VALUE, IND_WEIGHT, IND_UNITS = "VALUE_IN_EUROS", "QUANTITY_IN_100KG", "SUPPLEMENTARY_QUANTITY"
WEIGHT_SCALE = 0.1           # 100 kg -> tonnes
UNITS_COVER = 0.995          # a heading counts in one unit when its lines in that unit hold this share of its value
NOT_PUBLISHED = "no quantity published for this line"
SUPPL_PATH = Path(__file__).resolve().parent.parent / "suppl_units.json"
_SUPPL: list = []


def _suppl() -> dict:
    """{units: {code: {name, short}}, lines: {cn8: [[unit, from year, to year], ...]}} (see scripts/suppl_units.py)."""
    if not _SUPPL:
        try:
            _SUPPL.append(json.loads(SUPPL_PATH.read_text(encoding="utf-8")))
        except (OSError, ValueError):
            _SUPPL.append({"units": {}, "lines": {}})
    return _SUPPL[0]


def _measure_of(request: Request) -> Optional[str]:
    """The ``measure`` asked (value, weight, units, all), or None when the request does not name one."""
    m = request.query_params.get("measure")
    if m is None:
        return None
    if m not in MEASURES:
        raise HTTPException(400, f"measure is one of {', '.join(MEASURES)}, not {m!r}")
    return m


def _unit_info(unit: Optional[str]) -> dict:
    u = (_suppl()["units"].get(unit) or {}) if unit else {}
    return {"unit": u.get("short", unit), "unit_code": unit, "unit_name": u.get("name", unit)}


def _line_units(code: str, y0: int, y1: int) -> set:
    """The supplementary units of a CN8 line in the years y0..y1 (empty: counted by weight only)."""
    return {u for u, a, b in _suppl()["lines"].get(str(code), []) if a <= y1 and b >= y0}


def _years(lo: Optional[str], hi: Optional[str]) -> tuple[int, int]:
    y0 = int(str(lo)[:4]) if lo and str(lo)[:4].isdigit() else 1900
    y1 = int(str(hi)[:4]) if hi and str(hi)[:4].isdigit() else 9999
    return y0, y1


def _children_cn8(db: Session, code: str) -> list[str]:
    dim = DIMS["product"]
    rows = db.execute(text(f'SELECT code FROM "{dim["table"]}" WHERE code LIKE :p AND level = 4 ORDER BY code'),
                      {"p": f"{code}%"}).fetchall()
    return [r[0] for r in rows if str(r[0]).isdigit() and len(str(r[0])) == 8]


def _plan(db: Session, filters: dict, measure: str, lo: Optional[str], hi: Optional[str]) -> dict:
    """How to read one measure of a filtered slice: {filters, fetch, scale, unit...}, or {unavailable: why}.

    ``fetch`` are the filters of the slice to make sure of (both quantities come in one fetch)."""
    if measure == "value":
        return {"measure": "value", "filters": filters, "fetch": filters, "scale": 1.0, "unit": "€",
                "unit_name": "euros"}
    if measure == "weight":
        f = {**filters, IND_DIM: [IND_WEIGHT]}
        return {"measure": "weight", "filters": f, "fetch": {**filters, IND_DIM: [IND_WEIGHT, IND_UNITS]},
                "scale": WEIGHT_SCALE, "unit": "t", "unit_name": "tonnes (net mass)"}
    products = filters.get("product") or [DEFAULTS.get("product")]
    if len(products) != 1:
        return {"measure": "units", "unavailable": "units are counted for one product at a time"}
    code = str(products[0])
    y0, y1 = _years(lo, hi)
    if not code.isdigit() or len(code) not in (4, 6, 8):
        what = "Total goods are" if not code.isdigit() else f"The goods of chapter {code} are"
        return {"measure": "units", "unavailable": f"{what} counted in many different units (items, litres, pairs...): "
                "units exist for one product heading (4 digits) or line; weight (tonnes) exists for every product"}
    if len(code) == 8:
        units = _line_units(code, y0, y1)
        if len(units) != 1:
            return {"measure": "units", "unavailable": (
                f"line {code} has no supplementary unit: it is counted by weight (tonnes) only" if not units else
                f"line {code} changed its unit over these years ({', '.join(sorted(units))})")}
        lines, unit = [code], next(iter(units))
    else:
        kids = _children_cn8(db, code)
        by_unit: dict[str, list[str]] = {}
        for c in kids:
            for u in _line_units(c, y0, y1):
                by_unit.setdefault(u, []).append(c)
        if not by_unit:
            return {"measure": "units", "unavailable": (
                f"the lines under {code} have no supplementary unit: they are counted by weight (tonnes) only")}
        # the unit of the heading: the one most of its lines count in; checked against the value below
        unit = max(by_unit, key=lambda u: len(by_unit[u]))
        lines = by_unit[unit]
        others = sorted(set(by_unit) - {unit})
        plan = {"measure": "units", "check_lines": kids, "check_others": others}
    info = _unit_info(unit)
    f = {**filters, "product": lines, IND_DIM: [IND_UNITS]}
    out = {"measure": "units", "filters": f, "fetch": {**f, IND_DIM: [IND_WEIGHT, IND_UNITS]}, "scale": 1.0,
           "lines": lines, "of": code, **info}
    if len(code) != 8:
        out.update(plan)
    return out


def _measure_status(db: Session, plan: dict, lo: Optional[str], hi: Optional[str], probe: Callable[[], bool],
                    by: Optional[dict] = None, parent: Optional[str] = None, level: Optional[int] = None) -> dict:
    """Makes sure of a plan's slice (fetched live when it never was) and, for a heading counted in units, that
    its lines in that unit hold its value; returns the _ensure flags, with ``unavailable`` when they do not."""
    if plan.get("unavailable"):
        return {"fetched_live": False, "loaded": True}
    needed, extra = _needed(db, plan["fetch"], by, parent, level)
    status = _ensure(db, needed, extra, lo, hi, probe=probe)
    if not status["loaded"] or not plan.get("check_lines"):
        return status
    # A heading's units are the sum of its CN8 lines: only when the lines in that unit hold its value.
    vf = {**plan["filters"], "product": plan["check_lines"], IND_DIM: [IND_VALUE]}
    vn, ve = _needed(db, vf)
    st = _ensure(db, vn, ve, lo, hi, probe=lambda: False)
    if not st["loaded"]:
        return {**status, "loaded": False, "error": st.get("error")}
    params: dict = {}
    where = _where({k: v for k, v in vf.items() if DIMS[k].get("role") != "time"}, params)
    if lo:
        where.append(f'o."{TIME}" >= :lo')
        params["lo"] = lo
    if hi:
        where.append(f'o."{TIME}" <= :hi')
        params["hi"] = hi
    rows = db.execute(text(f'SELECT o."{DIMS["product"]["column"]}", SUM({VALUE_EXPR}) FROM "{OBS}" o '
                           f'WHERE {" AND ".join(where)} GROUP BY 1'), params).fetchall()
    total = sum(float(v or 0) for _, v in rows)
    counted = sum(float(v or 0) for c, v in rows if c in set(plan["lines"]))
    if total > 0 and counted / total < UNITS_COVER:
        others = ", ".join(_unit_info(u)["unit"] for u in plan.get("check_others") or []) or "weight only"
        plan["unavailable"] = (f"the lines under {plan['of']} are not all counted in {plan['unit']} "
                               f"({100 * (1 - counted / total):.1f}% of their value is counted in {others}): "
                               "ask about one line, or use weight (tonnes)")
    return status


def _measure_fields(plan: dict) -> dict:
    """What a response says about its measure: {measure, unit, unit_name} (and the lines summed, the reason)."""
    out = {"measure": plan["measure"]}
    if plan.get("unavailable"):
        return {**out, "unit": None, "unavailable": plan["unavailable"]}
    out.update({k: plan[k] for k in ("unit", "unit_code", "unit_name") if plan.get(k) is not None})
    if plan.get("lines") and plan.get("of") and len(plan["lines"]) > 1:
        out["summed_lines"] = len(plan["lines"])
    return out


def _unit_values(row: dict) -> None:
    """€ per tonne and € per unit of a row with value, weight and units (None when a quantity is missing)."""
    v, w, u = row.get("value"), row.get("weight"), row.get("units")
    row["eur_per_tonne"] = v / w if v and w else None
    row["eur_per_unit"] = v / u if v and u else None
    if not w and not u:
        row["quantity_note"] = NOT_PUBLISHED


# --------------------------------------------------------------------------- rankings
def _span(start: str, end: str) -> str:
    """The years a ranking sums over, as words for a text fact: 2025, or 2020–2025."""
    return str(end) if str(start) == str(end) else f"{start}–{end}"


def _ranking_periods(request: Request, period: str, filters: dict) -> tuple[str, str]:
    """Apply an inclusive annual range, or keep the existing single-period query."""
    start, end = request.query_params.get("start"), request.query_params.get("end")
    # start = end = period (a page that follows $start and $period on a single year or a month) is
    # the single-period query, so a month keeps reading the monthly data.
    if start in (None, period) and end in (None, period):
        filters[CONFIG["time_dimension"]] = [period]
        return period, period
    start, end = start or period, end or period
    if not re.fullmatch(r"[0-9]{4}", start) or not re.fullmatch(r"[0-9]{4}", end) or not (1 <= int(start) <= int(end) <= 9999):
        raise HTTPException(400, "Use an inclusive annual range with start <= end (YYYY).")
    freq = next((d for d in CONFIG["dimensions"] if d["id"] == "freq"), None)
    if freq and filters.get("freq") != [_normalise(freq, "A")]:
        raise HTTPException(400, "Year ranges require annual frequency (freq=A).")
    filters[CONFIG["time_dimension"]] = [str(y).zfill(4) for y in range(int(start), int(end) + 1)]
    return start, end


def _ranking(db: Session, request: Request, by_id: str, period: str, level: Optional[int], parent: Optional[str],
             threshold: Optional[float], max_items: int, relative_to: str) -> dict:
    """A ranking in euros; with ``measure`` weight or units, of that quantity (shares of its own total); with
    measure=all, in euros with each item's weight, units and unit values (see _rank_all)."""
    measure = _measure_of(request)
    quantity = measure if measure in ("weight", "units") else None
    r = _ranking_value(db, request, by_id, period, level, parent, threshold, max_items, relative_to, quantity)
    plan = r.pop("_plan", None)
    if plan is not None:
        s = plan["scale"]
        for k in ("total", "base_total"):
            if r.get(k) is not None:
                r[k] *= s
        for row in r.get("items") or []:
            row["value"] *= s
        for k in ("other", "unallocated"):
            if r.get(k):
                r[k]["value"] *= s
        r.update(_measure_fields(plan))
        if r.get("items"):   # each item's value in euros too, for a label or a tooltip that shows both
            by = _dim(by_id)
            vf = _filters(request, exclude={by_id}, db=db)
            _ranking_periods(request, period, vf)
            euros = _grouped(db, by, vf, r.get("level"), parent)
            for row in r["items"]:
                row["value_eur"] = euros.get(row["code"])
    elif measure == "value":
        r.update(measure="value", unit="€", unit_name="euros")
    elif measure == "all":
        _rank_all(db, request, r, by_id, period, parent)
    return r


def _rank_all(db: Session, request: Request, r: dict, by_id: str, period: str, parent: Optional[str]) -> None:
    """Adds to each item of a ranking in euros its weight (t), units (with ``unit``), € per tonne and € per unit;
    ``quantity_note`` where no quantity is published. Units: per CN8 line when ranking products (each line has its
    own unit), of the product filter's unit when ranking partners or reporters (a heading sums its CN8 lines)."""
    by = _dim(by_id)
    filters = _filters(request, exclude={by_id}, db=db)
    start, end = _ranking_periods(request, period, filters)
    level = r.get("level")
    y0, y1 = _years(start, end)
    wplan = _plan(db, filters, "weight", start, end)
    _measure_status(db, wplan, start, end, probe=lambda: True, by=by, parent=parent, level=level)
    weight = {c: v * WEIGHT_SCALE for c, v in _grouped(db, by, wplan["filters"], level, parent).items() if v}
    units: dict = {}
    unit_of: dict = {}
    measures = {"value": {"measure": "value", "unit": "€", "unit_name": "euros"}, "weight": _measure_fields(wplan)}
    if by_id == "product":
        f = {**filters, IND_DIM: [IND_UNITS]}
        units = {c: v for c, v in _grouped(db, by, f, level, parent).items() if v}
        for c in list(units):
            us = _line_units(c, y0, y1)
            if len(us) == 1:
                unit_of[c] = _unit_info(next(iter(us)))["unit"]
            else:
                units.pop(c)
        measures["units"] = {"measure": "units", "unit": "per line (each CN8 line's own unit)"}
    else:
        uplan = _plan(db, filters, "units", start, end)
        _measure_status(db, uplan, start, end, probe=lambda: True, by=by, parent=parent, level=level)
        measures["units"] = _measure_fields(uplan)
        if not uplan.get("unavailable"):
            units = {c: v for c, v in _grouped(db, by, uplan["filters"], level, parent).items() if v}
            unit_of = {c: uplan["unit"] for c in units}
    for row in r.get("items") or []:
        c = row["code"]
        row.update(weight=weight.get(c), units=units.get(c), unit=unit_of.get(c))
        _unit_values(row)
        if row["units"] is None and row["weight"] is not None and by_id == "product" and len(str(c)) != 8:
            row["units_note"] = "units are counted per CN8 line"
    r.update(measure="all", measures=measures)


def _ranking_value(db: Session, request: Request, by_id: str, period: str, level: Optional[int],
                   parent: Optional[str], threshold: Optional[float], max_items: int, relative_to: str,
                   quantity: Optional[str] = None) -> dict:
    by = _dim(by_id)
    filters = _filters(request, exclude={by_id}, db=db)
    start, end = _ranking_periods(request, period, filters)
    if parent:
        _check(db, by, [parent])
    level = _drill_level(db, by, level, parent)
    plan = None
    if quantity:
        if quantity == "units" and by_id == "product":
            raise HTTPException(400, "Units differ from line to line: rank products by value or weight, or read "
                                     "each line's units with measure=all.")
        plan = _plan(db, filters, quantity, start, end)
        _measure_status(db, plan, start, end, probe=lambda: True, by=by, parent=parent, level=level)
        if plan.get("unavailable"):
            raise HTTPException(422, plan["unavailable"][:1].upper() + plan["unavailable"][1:] + ".")
        filters = plan["filters"]

    def query() -> dict:
        values = _grouped(db, by, filters, level, parent)
        return {c: v for c, v in values.items() if _in_view(by, c, db, parent) and v > 0}

    items = query()
    needed, extra = _needed(db, filters, by, parent, level)
    status = _ensure(db, needed, extra, start, end, probe=lambda: bool(items))
    if status["fetched_live"]:
        items = query()
    if not status["loaded"]:
        return {"by": by_id, "period": period, "start": start, "end": end, "span": _span(start, end), "level": level, "parent": parent, "total": None, "base_total": None,
                "items": [], "other": None, **status, "_plan": plan}

    # Two totals: `view` is the value of what is on screen (the parent when drilling, else the
    # dimension's total) and gives the coverage and the "Other" bucket; `base` is what shares are
    # expressed in (the dimension's total, or the parent with relative_to=parent).
    view, base = _totals(db, by, filters, parent, relative_to, items)
    if not view or not base:
        return {"by": by_id, "period": period, "start": start, "end": end, "span": _span(start, end), "level": level, "parent": parent, "total": 0, "base_total": 0,
                "items": [], "other": None, **status, "_plan": plan}

    threshold = _default_threshold(by, level) if threshold is None else threshold
    ranked = sorted(items.items(), key=lambda kv: -kv[1])
    kept = [(c, v) for c, v in ranked if v / base >= threshold][:max_items]
    labels = _labels(db, by, [c for c, _ in kept])
    cum = 0.0
    out = []
    for rank, (c, v) in enumerate(kept, 1):
        cum += v
        out.append({"rank": rank, "code": c, "name": labels[c], "value": v, "share": v / base, "cum_share": cum / base})
    hidden = ranked[len(kept):]
    hidden_value = sum(v for _, v in hidden)
    # Value in view that no listed item accounts for: confidential or unallocated trade.
    unallocated = max(view - cum - hidden_value, 0.0)
    return {
        "by": by_id, "period": period, "start": start, "end": end, "span": _span(start, end), "level": level, "parent": parent, "threshold": threshold,
        "relative_to": relative_to, "total": view, "base_total": base, "coverage": cum / view, "items": out,
        "other": {"name": f"Other ({len(hidden)})", "value": hidden_value, "share": hidden_value / base,
                  "count": len(hidden)} if hidden else None,
        "unallocated": {"value": unallocated, "share": unallocated / base} if unallocated > 0.005 * view else None,
        **status, "_plan": plan,
    }


def _totals(db: Session, by: dict, filters: dict, parent: Optional[str], relative_to: str,
            items: dict[str, float]) -> tuple[float, float]:
    """(view total, base for shares) of a ranking; see _ranking."""
    total_code = by.get("total_code")
    dim_total = (_value_of(db, by, total_code, filters) if total_code else None) or sum(items.values())
    if not parent:
        return dim_total, dim_total
    parent_total = _value_of(db, by, parent, filters) or sum(items.values())
    return parent_total, (parent_total if relative_to == "parent" else dim_total)


# --------------------------------------------------------------------------- endpoints
def _unit(db: Session) -> dict:
    """Currency/unit of the values, from the codes the unit-like dimensions are fixed to."""
    words = []
    for d in CONFIG["dimensions"]:
        code = DEFAULTS.get(d["id"])
        if d.get("role") != "unit" or code is None:
            continue
        if d["kind"] == "enum":
            lit = _normalise(d, code)
            words += [lit, _enum_label(d, lit)]
        elif d["kind"] == "class":
            words += [code, _labels(db, d, [code])[code]]
    text_ = " ".join(words)
    symbol = "€" if re.search(r"EUR|EURO", text_, re.I) else "$" if re.search(r"USD|DOLLAR", text_, re.I) else \
        "%" if re.search(r"PERCENT|PC_|%", text_, re.I) else ""
    multiplier = 1.0
    if not UNIT_MULT:  # the unit's name may carry the scale ("Current prices, million euro")
        for word, m in (("thousand", 1e3), ("million", 1e6), ("billion", 1e9), ("MEUR", 1e6), ("MIO", 1e6)):
            if re.search(word, text_, re.I):
                multiplier = m
                break
    return {"symbol": symbol, "multiplier": multiplier, "label": text_}


@router.get("/meta")
def meta(db: Session = Depends(get_db)):
    """Dimensions, their codes or literals, and the periods available per frequency.

    Computed once per process: the data only changes when the loader runs again.
    """
    if _META_CACHE:
        return _META_CACHE[0]
    dims = []
    for d in CONFIG["dimensions"]:
        if d.get("role") == "time":
            continue
        entry = {k: d.get(k) for k in ("id", "label", "kind", "role", "hierarchy", "total_code")}
        entry["default"] = DEFAULTS.get(d["id"])
        present = {r[0] for r in db.execute(text(f'SELECT DISTINCT "{d["column"]}" FROM "{OBS}"')).fetchall()}
        entry["n_values"] = len(present)
        if d["kind"] == "enum":
            if entry["default"] is not None:
                entry["default"] = _normalise(d, entry["default"])
            # Only the literals that actually occur in the data (a codelist may list dozens more).
            lits = sorted(v for v in set(d["literals"].values()) if v in present) or sorted(set(d["literals"].values()))
            entry["values"] = [{"code": lit, "label": _enum_label(d, lit)} for lit in lits]
        if entry["default"] is not None and d["kind"] in ("enum", "class"):
            entry["default_label"] = _labels(db, d, [entry["default"]])[entry["default"]]
        # A dimension with one value in the data (or "not applicable") is context, not a choice.
        entry["constant"] = len(present) <= 1
        entry["not_applicable"] = bool(present) and present <= NOT_APPLICABLE
        dims.append(entry)
    freq = CONFIG.get("frequency_dimension")
    periods: dict[str, list[str]] = {}
    if freq:
        col = DIMS[freq]["column"]
        rows = db.execute(text(f'SELECT DISTINCT "{col}", "{TIME}" FROM "{OBS}" ORDER BY "{TIME}"')).fetchall()
        for f, p in rows:
            periods.setdefault(f, []).append(p)
    else:
        periods["all"] = [r[0] for r in db.execute(text(f'SELECT DISTINCT "{TIME}" FROM "{OBS}" ORDER BY 1')).fetchall()]
    defaults = {k: (_normalise(DIMS[k], v) if k in DIMS else v) for k, v in DEFAULTS.items()}
    # Each frequency's periods end with the last one the headline series has (every class dimension at its
    # default: reporter LU, partner WORLD, product TOTAL). Eurostat publishes some partners a month before the
    # total (extra-EU trade for July 2026, say); a month without the total is not one the page can show.
    if freq:
        where = [(DIMS[k]["column"], v) for k, v in defaults.items()
                 if k in DIMS and DIMS[k]["kind"] == "class" and v is not None]
        if where:
            cond = " AND ".join(f'"{c}" = :w{i}' for i, (c, _) in enumerate(where))
            last = dict(db.execute(text(f'SELECT "{col}", MAX("{TIME}") FROM "{OBS}" WHERE {cond} GROUP BY "{col}"'),
                                   {f"w{i}": v for i, (_, v) in enumerate(where)}).fetchall())
            periods = {f: [p for p in ps if not last.get(f) or p <= last[f]] for f, ps in periods.items()}
    # The last year with 12 months: later months are provisional (and revised by the source).
    monthly = periods.get("M", [])
    years = sorted({p[:4] for p in monthly})
    complete = [y for y in years if sum(1 for p in monthly if p.startswith(y)) == 12]
    result = {"title": CONFIG["title"], "dataflow": CONFIG["dataflow"], "source": CONFIG.get("source"),
              "live_source": (SDMX or {}).get("name"),
              "dimensions": dims, "periods": periods, "defaults": defaults, "base_threshold": CONFIG["base_threshold"],
              "focus": FOCUS, "time_dimension": CONFIG["time_dimension"], "unit": _unit(db),
              "complete_until": f"{complete[-1]}-12" if complete else None}
    _META_CACHE.append(result)
    return result


_META_CACHE: list[dict] = []


@router.get("/ranking")
def ranking(request: Request, by: str, period: str, level: Optional[int] = None, parent: Optional[str] = None,
            threshold: Optional[float] = None, max_items: int = 15, relative_to: str = "total",
            start: Optional[str] = None, end: Optional[str] = None, db: Session = Depends(get_db)):
    """Items of one dimension ranked by value, above a significance threshold, plus an 'Other' bucket."""
    return _ranking(db, request, by, period, level, parent, threshold, max_items, relative_to)


@router.get("/ranking/records")
def ranking_records(request: Request, by: str, period: str, level: Optional[int] = None, parent: Optional[str] = None,
                    threshold: Optional[float] = None, max_items: int = 15, relative_to: str = "total",
                    start: Optional[str] = None, end: Optional[str] = None, db: Session = Depends(get_db)):
    """Same as /ranking as a flat list (name, value, share) for BESSER chart components."""
    r = _ranking(db, request, by, period, level, parent, threshold, max_items, relative_to)
    rows = [{"name": i["name"], "code": i["code"], "value": i["value"], "share": round(100 * i["share"], 3)} for i in r["items"]]
    if r.get("measure"):   # measure asked: each row says its unit; with all, its quantities and unit values too
        keep = ("weight", "units", "unit", "eur_per_tonne", "eur_per_unit", "quantity_note", "units_note")
        for row, i in zip(rows, r["items"]):
            row.update({k: i[k] for k in keep if k in i} if r["measure"] == "all" else
                       {"unit": r.get("unit"), **({"value_eur": i["value_eur"]} if "value_eur" in i else {})})
    if r.get("other") and r["other"]["value"] > 0:
        rows.append({"name": r["other"]["name"], "code": "OTHER", "value": r["other"]["value"],
                     "share": round(100 * r["other"]["share"], 3)})
    return rows


@router.get("/ladder")
def ladder(request: Request, by: str, period: str, level: Optional[int] = None, parent: Optional[str] = None,
           relative_to: str = "total", start: Optional[str] = None, end: Optional[str] = None, db: Session = Depends(get_db)):
    """How many items pass each threshold (10% ... 0.001%) and what share of value they cover."""
    dim = _dim(by)
    filters = _filters(request, exclude={by}, db=db)
    start, end = _ranking_periods(request, period, filters)
    level = _drill_level(db, dim, level, parent)

    def query() -> dict:
        return {c: v for c, v in _grouped(db, dim, filters, level, parent).items()
                if _in_view(dim, c, db, parent) and v > 0}

    values = query()
    needed, extra = _needed(db, filters, dim, parent, level)
    status = _ensure(db, needed, extra, start, end, probe=lambda: bool(values))
    if status["fetched_live"]:
        values = query()
    if not status["loaded"]:
        return {"by": by, "period": period, "start": start, "end": end, "span": _span(start, end), "level": level, "total": None, "n_items": 0, "ladder": [], **status}
    view, base = _totals(db, dim, filters, parent, relative_to, values)
    rows = []
    for t in LADDER:  # cutoffs in shares of `base`, coverage of what is in view
        kept = [v for v in values.values() if base and v / base >= t]
        rows.append({"threshold": t, "label": f"≥ {t * 100:g}%", "items": len(kept),
                     "coverage": (sum(kept) / view) if view else 0})
    return {"by": by, "period": period, "start": start, "end": end, "span": _span(start, end), "level": level, "total": view, "base_total": base,
            "n_items": len(values), "ladder": rows, **status}


# Seasonal adjustment (/insights/series?adjust=true): robust STL, period 12, on the slice's whole monthly
# history. Below five years robust STL degenerates: on 36 to 48 months of Luxembourg's trade series it gives
# half to two thirds of the months a remainder of exactly zero, so "adjusted" is the trend there (measured on
# exports in total, to the US, to Germany, chapter 72 and 84 imports/exports, imports from France); from 60
# months the share of such months falls under a tenth. So: at least 60 months, else "too short to adjust".
ADJUST_PERIOD = 12
ADJUST_MIN_MONTHS = 60
_MONTH = re.compile(r"^\d{4}-(0[1-9]|1[0-2])$")


def _history_rows(db: Session, filters: dict) -> list[dict]:
    """Every period of the filtered slice, oldest first: the history a seasonal adjustment is fitted on."""
    params: dict = {}
    where = _where(filters, params)
    sql = (f'SELECT o."{TIME}", SUM({VALUE_EXPR}) FROM "{OBS}" o WHERE {" AND ".join(where) or "1=1"} '
           f'GROUP BY o."{TIME}" ORDER BY o."{TIME}"')
    return [{"period": p, "value": float(v or 0)} for p, v in db.execute(text(sql), params).fetchall()]


def _month_index(period: str) -> int:
    return int(period[:4]) * 12 + int(period[5:7]) - 1


def _adjust_rows(rows: list[dict], history: list[dict]) -> None:
    """Adds ``adjusted`` (= value - seasonal), ``trend`` and ``seasonal`` to ``rows`` from one robust STL fit
    of ``history`` (the slice's whole monthly history, of which ``rows`` is a window).

    A month inside the history with no row at all (no trade recorded) counts as zero, so the fit's months
    are consecutive. Raises 422 when the data is not monthly, or the history spans, or has trade in, fewer than
    ADJUST_MIN_MONTHS months.
    """
    if not all(_MONTH.match(str(r["period"])) for r in history) or not all(_MONTH.match(str(r["period"])) for r in rows):
        raise HTTPException(422, "Seasonal adjustment needs monthly data (freq=M): this series is not monthly.")
    first = _month_index(history[0]["period"])
    n = _month_index(history[-1]["period"]) - first + 1
    recorded = sum(1 for r in history if r["value"])
    if min(n, recorded) < ADJUST_MIN_MONTHS:
        what = (f"{n} months of data ({history[0]['period']} to {history[-1]['period']})" if n < ADJUST_MIN_MONTHS else
                f"trade recorded in only {recorded} of its {n} months ({history[0]['period']} to {history[-1]['period']})")
        raise HTTPException(422, (
            f"Too short to adjust: this selection has {what}; taking out the usual month-to-month pattern needs "
            f"at least {ADJUST_MIN_MONTHS} months (five years). The values are shown as recorded."))
    import numpy as np
    values = np.zeros(n)
    for r in history:
        values[_month_index(r["period"]) - first] = r["value"]
    try:
        from statsmodels.tsa.seasonal import STL
        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            res = STL(values, period=ADJUST_PERIOD, robust=True).fit()
    except Exception as exc:  # statsmodels missing, or a numerical failure
        raise HTTPException(500, f"Seasonal adjustment failed: {exc}")
    for r in rows:
        i = _month_index(r["period"]) - first
        if not 0 <= i < n:  # a month the history query did not see (cannot happen for one slice)
            raise HTTPException(500, f"Seasonal adjustment failed: {r['period']} is outside the fitted history")
        seasonal = float(res.seasonal[i])
        r["adjusted"] = r["value"] - seasonal
        r["trend"] = float(res.trend[i])
        r["seasonal"] = seasonal


@router.get("/series")
def series(request: Request, adjust: bool = False, start: Optional[str] = None, end: Optional[str] = None,
           envelope: bool = False, db: Session = Depends(get_db)):
    """A time series for the filtered slice; ``adjust=true`` adds a seasonally adjusted value (STL) for monthly data.

    With ``adjust=true`` each row also has ``adjusted`` (value minus ``seasonal``), ``trend`` and ``seasonal``,
    from one robust STL fit (period 12) of the slice's whole monthly history, cut to start..end. A series that
    is not monthly or has under ADJUST_MIN_MONTHS months of history is refused (422, "Too short to adjust").

    ``envelope=true`` wraps the rows with the live-fetch flags: ``{"rows": [...], "fetched_live", "loaded"}``.

    ``measure`` (weight, units or all; value, in euros, is the default) reads the quantities: see _series_measure.
    """
    filters = _filters(request, exclude={CONFIG["time_dimension"]}, db=db)
    measure = _measure_of(request)
    if measure not in (None, "value"):
        return _series_measure(db, filters, measure, start, end, envelope, adjust)

    def query() -> list[dict]:
        params: dict = {}
        where = _where(filters, params)
        if start:
            where.append(f'o."{TIME}" >= :start')
            params["start"] = start
        if end:
            where.append(f'o."{TIME}" <= :end')
            params["end"] = end
        sql = (f'SELECT o."{TIME}", SUM({VALUE_EXPR}) FROM "{OBS}" o WHERE {" AND ".join(where) or "1=1"} '
               f'GROUP BY o."{TIME}" ORDER BY o."{TIME}"')
        return [{"period": p, "value": float(v or 0)} for p, v in db.execute(text(sql), params).fetchall()]

    rows = query()
    freq = CONFIG.get("frequency_dimension")
    known = meta(db)["periods"]
    span = known.get(filters.get(freq, [None])[0], []) if freq else known.get("all", [])
    lo, hi = start or (span[0] if span else None), end or (span[-1] if span else None)
    needed, extra = _needed(db, filters)
    status = _ensure(db, needed, extra, lo, hi, probe=lambda: bool(rows))
    if status["fetched_live"]:
        rows = query()
    if adjust and status["loaded"] and rows:
        history = rows
        if start or end:
            # Fitted on the whole monthly history of the slice, never on the window alone: a few years of
            # robust STL leave most months with a zero remainder (adjusted = trend). The months shown are
            # then cut from that fit. The history is what the database holds (the window itself was made sure
            # of above): no live fetch of decades of data behind a toggle.
            history = _history_rows(db, filters)
        _adjust_rows(rows, history)
    if envelope:
        return {"rows": rows if status["loaded"] else [], **status}
    return rows


def _measure_rows(db: Session, plan: dict, start: Optional[str], end: Optional[str]) -> dict[str, float]:
    """{period: value in the plan's unit} of a series. A quantity of 0 or no row is 'not published', never 0."""
    params: dict = {}
    where = _where(plan["filters"], params)
    if start:
        where.append(f'o."{TIME}" >= :start')
        params["start"] = start
    if end:
        where.append(f'o."{TIME}" <= :end')
        params["end"] = end
    sql = (f'SELECT o."{TIME}", SUM({VALUE_EXPR}) FROM "{OBS}" o WHERE {" AND ".join(where) or "1=1"} '
           f'GROUP BY o."{TIME}" ORDER BY o."{TIME}"')
    quantity = plan["measure"] != "value"
    return {p: float(v or 0) * plan["scale"] for p, v in db.execute(text(sql), params).fetchall()
            if not (quantity and not v)}


def _series_measure(db: Session, filters: dict, measure: str, start: Optional[str], end: Optional[str],
                    envelope: bool, adjust: bool):
    """/series with measure=weight, units or all.

    weight and units: rows ``{period, value, unit}`` in tonnes, or in the supplementary unit ("items", "litres"),
    a period with no published quantity having no row; a slice with no such unit is a 422 that says why
    ("counted by weight only"). all: rows ``{period, value (€), weight (t), units, unit, eur_per_tonne,
    eur_per_unit}``, a missing quantity None with ``quantity_note`` (and ``units_note`` when there is no unit).
    """
    if adjust:
        raise HTTPException(422, "Seasonal adjustment is computed on values in euros only.")
    freq = CONFIG.get("frequency_dimension")
    known = meta(db)["periods"]
    span = known.get(filters.get(freq, [None])[0], []) if freq else known.get("all", [])
    lo, hi = start or (span[0] if span else None), end or (span[-1] if span else None)
    names = ["value", "weight", "units"] if measure == "all" else [measure]
    plans = {m: _plan(db, filters, m, lo, hi) for m in names}
    status: dict = {"fetched_live": False, "loaded": True}
    data: dict[str, dict] = {}
    for m, plan in plans.items():
        st = _measure_status(db, plan, lo, hi, probe=lambda p=plan: bool(_measure_rows(db, p, start, end)))
        status["fetched_live"] = status["fetched_live"] or st.get("fetched_live", False)
        if not st["loaded"]:
            if m == "value" or measure != "all":
                status.update(loaded=False, error=st.get("error"))
            plan.setdefault("unavailable", "the source could not be reached")
        data[m] = {} if plan.get("unavailable") else _measure_rows(db, plan, start, end)
    if measure != "all":
        plan = plans[measure]
        if plan.get("unavailable") and status["loaded"]:
            raise HTTPException(422, plan["unavailable"][:1].upper() + plan["unavailable"][1:] + ".")
        # the value in euros of the same goods, for a label or a tooltip that shows both
        euros = _measure_rows(db, _plan(db, filters, "value", lo, hi), start, end)
        rows = [{"period": p, "value": v, "unit": plan["unit"], "value_eur": euros.get(p)}
                for p, v in sorted(data[measure].items())]
        if envelope:
            return {"rows": rows if status["loaded"] else [], **_measure_fields(plan), **status}
        return rows
    units = plans["units"]
    unit = None if units.get("unavailable") else units.get("unit")
    rows = []
    for p in sorted(set(data["value"]) | set(data["weight"]) | set(data["units"])):
        r = {"period": p, "value": data["value"].get(p), "weight": data["weight"].get(p),
             "units": data["units"].get(p), "unit": unit}
        _unit_values(r)
        if units.get("unavailable"):
            r["units_note"] = units["unavailable"]
        rows.append(r)
    if envelope:
        return {"rows": rows if status["loaded"] else [], "measure": "all",
                "measures": {m: _measure_fields(p) for m, p in plans.items()}, **status}
    return rows


@router.get("/movers")
def movers(request: Request, by: str, period: str, previous: str, level: Optional[int] = None,
           parent: Optional[str] = None, threshold: Optional[float] = None, limit: int = 10,
           db: Session = Depends(get_db)):
    """Largest increases and decreases between two periods among significant items.

    ``total`` and ``previous_total`` are the totals of the whole selection in ``period`` and
    ``previous`` (the dimension's total, or ``parent`` when drilling), so that ``previous_total``
    plus every change (shown or not) adds up to ``total``: what a waterfall needs."""
    dim = _dim(by)
    tdim = CONFIG["time_dimension"]
    filters = _filters(request, exclude={by}, db=db)
    if parent:
        _check(db, dim, [parent])
    level = _drill_level(db, dim, level, parent)
    plan = _quantity_plan(db, request, filters, by, *_window(period, previous), dim, parent, level)
    if plan:
        filters = plan["filters"]
    scale = plan["scale"] if plan else 1.0
    needed, extra = _needed(db, filters, dim, parent, level)

    def query(p: str) -> dict:
        return {c: v * scale for c, v in _grouped(db, dim, {**filters, tdim: [p]}, level, parent).items()}

    now, before = query(period), query(previous)
    # Both periods must be loaded, or "is_new" would just mean "not loaded".
    status = _ensure(db, needed, extra, *_window(period, previous), probe=lambda: bool(now) and bool(before))
    if status["fetched_live"]:
        now, before = query(period), query(previous)
    if not status["loaded"]:
        return {"by": by, "period": period, "previous": previous, "total": None, "previous_total": None,
                "up": [], "down": [], "new": [], **status}
    total = sum(v for c, v in now.items() if _in_view(dim, c, db, parent))
    total_now, _ = _totals(db, dim, {**filters, tdim: [period]}, parent, "total",
                           {c: v for c, v in now.items() if _in_view(dim, c, db, parent)})
    total_before, _ = _totals(db, dim, {**filters, tdim: [previous]}, parent, "total",
                              {c: v for c, v in before.items() if _in_view(dim, c, db, parent)})
    if plan and scale != 1.0:   # _totals reads the stored values (100 kg)
        total_now, total_before = total_now * scale, total_before * scale
    threshold = _default_threshold(dim, level) if threshold is None else threshold
    rows = []
    for c in set(now) | set(before):
        if not _in_view(dim, c, db, parent):
            continue
        a, b = before.get(c, 0.0), now.get(c, 0.0)
        if total and max(a, b) / total < threshold:
            continue
        rows.append({"code": c, "previous": a, "value": b, "change": b - a,
                     "growth": (b - a) / a if a else None, "is_new": a == 0 and b > 0})
    labels = _labels(db, dim, [r["code"] for r in rows])
    for r in rows:
        r["name"] = labels[r["code"]]
    rows.sort(key=lambda r: -r["change"])
    return {"by": by, "period": period, "previous": previous, "threshold": threshold,
            "total": total_now, "previous_total": total_before,
            # increases and decreases only, so no item is both (a waterfall would count it twice)
            "up": [r for r in rows if r["change"] > 0][:limit],
            "down": sorted((r for r in rows if r["change"] < 0), key=lambda r: r["change"])[:limit],
            "new": [r for r in rows if r["is_new"]][:limit], **status,
            **(_measure_fields(plan) if plan else {})}


def _quantity_plan(db: Session, request: Request, filters: dict, by_id: str, lo: Optional[str], hi: Optional[str],
                   by: Optional[dict] = None, parent: Optional[str] = None, level: Optional[int] = None) -> Optional[dict]:
    """The plan of measure=weight or units for an endpoint that reads one measure (None for euros); 422 with the
    reason when the slice has no such quantity, 400 for measure=all."""
    measure = _measure_of(request)
    if measure in (None, "value"):
        return None
    if measure == "all":
        raise HTTPException(400, "This endpoint reads one measure at a time: value, weight or units.")
    if measure == "units" and by_id == "product":
        raise HTTPException(400, "Units differ from line to line: compare products by value or weight.")
    plan = _plan(db, filters, measure, lo, hi)
    _measure_status(db, plan, lo, hi, probe=lambda: True, by=by, parent=parent, level=level)
    if plan.get("unavailable"):
        raise HTTPException(422, plan["unavailable"][:1].upper() + plan["unavailable"][1:] + ".")
    return plan


@router.get("/compare")
def compare(request: Request, by: str, period: str, group: Optional[str] = None, db: Session = Depends(get_db)):
    """Values for several items of one dimension (e.g. reporters LU, BE, DE) in one period.

    With ``group``, each member's slice is made sure of (fetched live when it never was): ``?by=reporter&
    group=LU,BE,NL&partner=US`` gives each country's own trade with the United States. A member that could not be
    read has ``value: null`` and ``loaded: false``, never 0. ``measure`` weight or units reads that quantity."""
    dim = _dim(by)
    filters = _filters(request, exclude={by}, db=db)
    filters[CONFIG["time_dimension"]] = [period]
    if group:
        filters[by] = [_normalise(dim, g) for g in group.split(",")]
        _check(db, dim, filters[by])
    plan = _quantity_plan(db, request, filters, by, period, period, dim)
    if plan:
        filters = plan["filters"]
    values = _grouped(db, dim, filters, None, None)
    missing: list = []
    if group:
        refetched = False
        for g in filters[by]:
            needed, extra = _needed(db, {**filters, by: [g]})
            st = _ensure(db, needed, extra, period, period, probe=lambda g=g: g in values)
            refetched = refetched or st["fetched_live"]
            if not st["loaded"]:
                missing.append(g)
        if refetched:
            values = _grouped(db, dim, filters, None, None)
    scale = plan["scale"] if plan else 1.0
    values = {c: v * scale for c, v in values.items() if c not in missing}
    labels = _labels(db, dim, list(values) + missing)
    total = sum(values.values())
    extra_fields = {"unit": plan["unit"]} if plan else {}
    rows = sorted(({"code": c, "name": labels[c], "value": v, "share": v / total if total else 0, **extra_fields}
                   for c, v in values.items()), key=lambda r: -r["value"])
    return rows + [{"code": c, "name": labels[c], "value": None, "share": None, "loaded": False} for c in missing]


@router.get("/compare/records")
def compare_records(request: Request, by: str, period: str, base: Optional[str] = None, limit: int = 30,
                    db: Session = Depends(get_db)):
    """One row per member of ``by`` (e.g. reporting countries): its value in ``period`` and its growth
    since ``base`` (default: the first period in the data), ranked by growth. The focus (e.g.
    Luxembourg) is flagged and named with a marker, so a bar chart shows where it stands."""
    dim = _dim(by)
    filters = _filters(request, exclude={by}, db=db)
    freq = CONFIG.get("frequency_dimension")
    periods = meta(db)["periods"]
    span = periods.get(filters.get(freq, [None])[0], []) if freq else periods.get("all", [])
    base = base or (span[0] if span else period)
    now = _grouped(db, dim, {**filters, CONFIG["time_dimension"]: [period]}, None, None)
    before = _grouped(db, dim, {**filters, CONFIG["time_dimension"]: [base]}, None, None)
    codes = [c for c in now if _is_member(dim, c, db) and before.get(c)]
    labels = _labels(db, dim, codes)
    focus = FOCUS.get(by)
    rows = [{"code": c, "name": labels[c] + (" ◀" if c == focus else ""), "value": now[c], "base_value": before[c],
             "growth": round(100 * (now[c] / before[c] - 1), 1), "is_focus": c == focus} for c in codes]
    rows.sort(key=lambda r: -r["growth"])
    return rows[:limit]


@router.get("/specialisation")
def specialisation(request: Request, by: str, period: str, db: Session = Depends(get_db)):
    """Revealed comparative advantage of the focus reporter vs its peer group, per item of ``by``.

    RCA = (focus share of item in its total) / (peer-group share of item in its total).
    Above 1: the focus trades relatively more of that item than its peers.
    """
    cfg = CONFIG.get("comparison")
    if not cfg:
        raise HTTPException(400, "No comparison dimension configured")
    dim = _dim(by)
    cmp_dim = _dim(cfg["dimension"])
    focus = request.query_params.get(cfg["dimension"], DEFAULTS.get(cfg["dimension"]))
    peers = cfg.get("peers") or "auto"
    if peers == "auto":
        col = cmp_dim["column"]
        rows = db.execute(text(f'SELECT DISTINCT "{col}" FROM "{OBS}"')).fetchall()
        peers = [r[0] for r in rows if r[0] != focus and _is_member(cmp_dim, r[0], db)]
    filters = _filters(request, exclude={by, cfg["dimension"]}, db=db)
    filters[CONFIG["time_dimension"]] = [period]
    level = _drill_level(db, dim, None, None)
    f_vals = {c: v for c, v in _grouped(db, dim, {**filters, cfg["dimension"]: [focus]}, level, None).items()
              if _is_member(dim, c, db)}
    p_vals = {c: v for c, v in _grouped(db, dim, {**filters, cfg["dimension"]: peers}, level, None).items()
              if _is_member(dim, c, db)}
    f_tot, p_tot = sum(f_vals.values()), sum(p_vals.values())
    labels = _labels(db, dim, list(f_vals))
    rows = []
    for c, v in f_vals.items():
        if not (f_tot and p_tot and p_vals.get(c)):
            continue
        fs, ps = v / f_tot, p_vals[c] / p_tot
        rows.append({"code": c, "name": labels[c], "value": v, "share": fs, "peer_share": ps, "rca": fs / ps})
    rows.sort(key=lambda r: -r["rca"])
    return {"by": by, "period": period, "focus": focus, "peers": peers, "items": rows}


@router.get("/specialisation/records")
def specialisation_records(request: Request, by: str, period: str, limit: int = 12, db: Session = Depends(get_db)):
    """Top items by RCA (above 1 only) as a flat list for BESSER chart components."""
    rows = specialisation(request, by, period, db)["items"]
    return [{"name": r["name"], "code": r["code"], "rca": round(r["rca"], 2), "value": r["value"]}
            for r in rows if r["rca"] > 1][:limit]


# =========================================================================== endpoints for agents
# Written by hand (not generated): what the agents of the view spec read (see docs/agents.md).
# trend and forecast fit models on the series; trends ranks the members of a dimension by growth;
# events serves the curated list in events.json; flows is the crossroads (imports by partner,
# Luxembourg, exports by partner) in one call. Same dimension filters as every endpoint above.
PER_YEAR = {"A": 1, "S": 2, "Q": 4, "M": 12}
TREND_METHODS = {"auto", "ols_log", "ols", "stl"}
FORECAST_MIN_MONTHS = 36          # the models live in app/backend/forecasting
EVENTS_PATH = Path(__file__).resolve().parent.parent / "events.json"
EVENT_KINDS = {"agreement", "dispute", "tariff", "sanction", "war", "disaster", "pandemic", "policy", "shock"}
FLOW_BY = "partner"
_FORECAST_CACHE: dict = {}
_EVENTS_CACHE: list = []


def _freq_of(filters: dict) -> str:
    freq = CONFIG.get("frequency_dimension")
    return (filters.get(freq) or ["A"])[0] if freq else "A"


def _month_bounds(start: Optional[str], end: Optional[str], freq: str) -> tuple[Optional[str], Optional[str]]:
    """Years as bounds of a sub-annual series: 2018 -> 2018-01 (start), 2025 -> 2025-12 (end)."""
    if freq == "A":
        return start, end
    if start and re.fullmatch(r"\d{4}", start):
        start = f"{start}-01"
    if end and re.fullmatch(r"\d{4}", end):
        end = f"{end}-12"
    return start, end


def _month_add(period: str, k: int) -> str:
    i = int(period[:4]) * 12 + int(period[5:7]) - 1 + k
    return f"{i // 12}-{i % 12 + 1:02d}"


def _years_between(a: str, b: str) -> float:
    """Years from period a to period b (2015 -> 2025: 10; 2015-01 -> 2025-01: 10)."""
    def idx(p: str) -> float:
        return int(p[:4]) + ((int(p[5:7]) - 1) / 12 if len(p) >= 7 else 0)
    return idx(b) - idx(a)


def _series_rows(db: Session, filters: dict, start: Optional[str], end: Optional[str]) -> tuple[list[dict], dict]:
    """(rows, live-fetch status) of the series for a slice, as /series computes it."""
    def query() -> list[dict]:
        params: dict = {}
        where = _where(filters, params)
        if start:
            where.append(f'o."{TIME}" >= :start')
            params["start"] = start
        if end:
            where.append(f'o."{TIME}" <= :end')
            params["end"] = end
        sql = (f'SELECT o."{TIME}", SUM({VALUE_EXPR}) FROM "{OBS}" o WHERE {" AND ".join(where) or "1=1"} '
               f'GROUP BY o."{TIME}" ORDER BY o."{TIME}"')
        return [{"period": p, "value": float(v or 0)} for p, v in db.execute(text(sql), params).fetchall()]

    rows = query()
    freq = CONFIG.get("frequency_dimension")
    known = meta(db)["periods"]
    span = known.get(filters.get(freq, [None])[0], []) if freq else known.get("all", [])
    lo, hi = start or (span[0] if span else None), end or (span[-1] if span else None)
    needed, extra = _needed(db, filters)
    status = _ensure(db, needed, extra, lo, hi, probe=lambda: bool(rows))
    if status["fetched_live"]:
        rows = query()
    return rows, status


def _ols(x, y) -> tuple[float, float, "object", float]:
    """Least squares y = a + b x: (a, b, fitted values, R squared)."""
    import numpy as np
    b, a = np.polyfit(x, y, 1)
    fit = a + b * x
    ss_tot = float(((y - y.mean()) ** 2).sum())
    r2 = 1 - float(((y - fit) ** 2).sum()) / ss_tot if ss_tot > 0 else 1.0
    return float(a), float(b), fit, r2


@router.get("/trend")
def trend(request: Request, start: Optional[str] = None, end: Optional[str] = None, adjust: bool = False,
          method: str = "auto", db: Session = Depends(get_db)):
    """The trend of the filtered series and how steep it is.

    Annual data: least squares on the logs (``ols_log``), so the slope is a growth rate. Monthly
    data: the STL trend component (robust, period 12), with a log-linear fit of that trend for the
    slope. ``slope_pct_per_period`` is in percent per period; ``slope_per_year``, ``cagr`` (from the
    first to the last value; the STL trend's for monthly data) and ``r2`` are fractions.
    ``method`` forces ``ols_log``, ``ols`` (linear, for series with zeros or negatives) or ``stl``.
    """
    import numpy as np

    if method not in TREND_METHODS:
        raise HTTPException(400, f"Unknown method {method!r}; use one of {sorted(TREND_METHODS)}")
    filters = _filters(request, exclude={CONFIG["time_dimension"]}, db=db)
    freq = _freq_of(filters)
    start, end = _month_bounds(start, end, freq)
    rows, status = _series_rows(db, filters, start, end)
    if not status["loaded"]:
        return {"method": None, "freq": freq, "start": start, "end": end, "n_obs": 0, "slope_pct_per_period": None,
                "slope_per_year": None, "cagr": None, "r2": None, "start_value": None, "end_value": None,
                "fitted": [], "rows": [], **status}
    if len(rows) < 3:
        raise HTTPException(400, f"A trend needs at least 3 periods; this slice has {len(rows)}")
    per_year = PER_YEAR.get(freq, 1)
    values = np.array([r["value"] for r in rows], float)
    seasonal = per_year > 1 and len(rows) >= 2 * per_year + 1
    # The STL trend comes from one fit of the slice's whole history (trends.analysis.stl_on_history, at least
    # five years), cut to the span: the span's first month is not an edge of the data. The slope and the
    # growth rate are then measured on the span only.
    fit, too_short = None, None
    if seasonal and method in ("auto", "stl"):
        from trends.analysis import TooShort, stl_on_history
        try:
            fit = stl_on_history(_history_rows(db, filters) if (start or end) else rows, per_year)
        except TooShort as exc:
            too_short = str(exc)
    if method == "auto":
        method = "stl" if fit else ("ols_log" if (values > 0).all() else "ols")
    if method == "stl":
        if not fit:
            raise HTTPException(400, too_short or "The STL trend needs a monthly or quarterly series of at least two years")
        smooth = np.asarray([fit[r["period"]][0] for r in rows], float)
    else:
        smooth = values
    x = np.arange(len(rows), dtype=float)
    if method != "ols" and (smooth > 0).all():
        _, b, fit, r2 = _ols(x, np.log(smooth))
        fitted = smooth if method == "stl" else np.exp(fit)
        slope_pct, slope_year = 100 * (math.exp(b) - 1), math.exp(b * per_year) - 1
    else:
        if method == "ols_log":
            raise HTTPException(400, "ols_log needs a positive series; use method=ols")
        _, b, fit, r2 = _ols(x, smooth)
        fitted = smooth if method == "stl" else fit
        scale = abs(float(smooth.mean())) or 1.0
        slope_pct, slope_year = 100 * b / scale, b * per_year / scale
    ends = smooth if method == "stl" else values
    first, last = float(ends[0]), float(ends[-1])
    years = (len(rows) - 1) / per_year
    cagr = (last / first) ** (1 / years) - 1 if first > 0 and last > 0 and years > 0 else None
    word = {1: "annual", 2: "half-yearly", 4: "quarterly", 12: "monthly"}.get(per_year, "")
    labels = {"ols_log": f"log-linear least squares on the {word} values",
              "ols": f"linear least squares on the {word} values",
              "stl": (f"STL trend of the whole {word} history, cut to {rows[0]['period']}–{rows[-1]['period']}, "
                      "with a log-linear fit over that span for the slope")}
    return {
        "method": method, "method_label": labels[method], "freq": freq,
        "start": rows[0]["period"], "end": rows[-1]["period"], "n_obs": len(rows),
        "slope_pct_per_period": slope_pct, "slope_per_year": slope_year, "cagr": cagr, "r2": r2,
        "start_value": first, "end_value": last,
        "fitted": [{"period": r["period"], "value": float(f)} for r, f in zip(rows, fitted)],
        "rows": [{"period": r["period"], "value": r["value"], "fitted": float(f)} for r, f in zip(rows, fitted)],
        **status,
    }


def _grouped_by_period(db: Session, by: dict, filters: dict, level: Optional[int], parent: Optional[str],
                       start: str, end: str) -> dict[str, dict[str, float]]:
    """{code: {period: value}} for the members of ``by`` between two periods."""
    params: dict = {"p_start": start, "p_end": end}
    where = _where(filters, params) + [f'o."{TIME}" >= :p_start', f'o."{TIME}" <= :p_end']
    join = ""
    if by.get("hierarchy"):
        join = f'JOIN "{by["table"]}" d ON d.code = o."{by["column"]}"'
        if level is not None:
            where.append("d.level = :lvl")
            params["lvl"] = level
        if parent:
            where.append(f'd."{by["parent_column"]}" = :parent')
            params["parent"] = parent
    sql = (f'SELECT o."{by["column"]}", o."{TIME}", SUM({VALUE_EXPR}) FROM "{OBS}" o {join} '
           f'WHERE {" AND ".join(where)} GROUP BY o."{by["column"]}", o."{TIME}"')
    out: dict[str, dict[str, float]] = {}
    for code, period, value in db.execute(text(sql), params).fetchall():
        out.setdefault(code, {})[period] = float(value or 0)
    return out


@router.get("/trends")
def trends(request: Request, by: str, start: Optional[str] = None, end: Optional[str] = None,
           period: Optional[str] = None, base: Optional[str] = None, level: Optional[int] = None,
           parent: Optional[str] = None, threshold: Optional[float] = None, limit: int = 10,
           method: str = "cagr", db: Session = Depends(get_db)):
    """Members of ``by`` ranked by growth from ``start`` (alias ``base``) to ``end`` (alias ``period``).

    Only members above the significance ladder (their share of the total, at the start or at the
    end) are ranked, so tiny items with huge growth rates do not crowd the list. ``growth`` is the
    compound annual growth rate (a fraction); ``slope_per_year`` the log-linear fit over every
    period. ``method=slope`` ranks by the fit instead. ``falling`` lists the steepest declines and
    ``new`` the members with no value at the start.
    """
    import numpy as np

    if method not in ("cagr", "slope"):
        raise HTTPException(400, "method is cagr (compound annual growth) or slope (log-linear fit)")
    dim = _dim(by)
    tdim = CONFIG["time_dimension"]
    filters = _filters(request, exclude={by, tdim}, db=db)
    if parent:
        _check(db, dim, [parent])
    level = _drill_level(db, dim, level, parent)
    freq = _freq_of(filters)
    span = meta(db)["periods"].get(freq, [])
    start = start or base or (span[0] if span else None)
    end = end or period or (span[-1] if span else None)
    if not start or not end:
        raise HTTPException(400, "No periods for this frequency; give start and end")
    lo, hi = _month_bounds(start, end, freq)
    if lo >= hi:
        raise HTTPException(400, f"start ({start}) must be before end ({end})")

    def query() -> dict:
        return {c: s for c, s in _grouped_by_period(db, dim, filters, level, parent, lo, hi).items()
                if _in_view(dim, c, db, parent)}

    data = query()
    needed, extra = _needed(db, filters, dim, parent, level)
    status = _ensure(db, needed, extra, start, end, probe=lambda: bool(data))
    if status["fetched_live"]:
        data = query()
    head = {"by": by, "level": level, "parent": parent, "method": method}
    periods = sorted({p for s in data.values() for p in s})
    if not status["loaded"] or len(periods) < 2:
        return {**head, "start": start, "end": end, "period": end, "base": start, "threshold": threshold,
                "total": None, "n_significant": 0, "items": [], "falling": [], "new": [], **status}
    p0, p1 = periods[0], periods[-1]
    years = _years_between(p0, p1)
    v_start = {c: s.get(p0, 0.0) for c, s in data.items()}
    v_end = {c: s.get(p1, 0.0) for c, s in data.items()}
    _, base_start = _totals(db, dim, {**filters, tdim: [p0]}, parent, "total", v_start)
    view_end, base_end = _totals(db, dim, {**filters, tdim: [p1]}, parent, "total", v_end)
    threshold = _default_threshold(dim, level) if threshold is None else threshold
    offsets = {p: _years_between(p0, p) for p in periods}
    rows = []
    for c, s in data.items():
        a, b = v_start[c], v_end[c]
        share0 = a / base_start if base_start else 0.0
        share1 = b / base_end if base_end else 0.0
        if max(share0, share1) < threshold:
            continue
        cagr = (b / a) ** (1 / years) - 1 if a > 0 and b > 0 and years > 0 else None
        points = [(offsets[p], v) for p, v in sorted(s.items()) if v > 0]
        slope = r2 = None
        if len(points) >= 3:
            _, k, _, r2 = _ols(np.array([p for p, _ in points]), np.log(np.array([v for _, v in points])))
            slope = math.exp(k) - 1
        rows.append({"code": c, "value": b, "start_value": a, "growth": cagr, "cagr": cagr,
                     "slope_per_year": slope, "r2": r2, "share": share1, "is_new": a <= 0 < b})
    labels = _labels(db, dim, [r["code"] for r in rows])
    for r in rows:
        r["name"] = labels[r["code"]]
    key = "growth" if method == "cagr" else "slope_per_year"
    ranked = sorted((r for r in rows if r[key] is not None), key=lambda r: -r[key])
    for rank, r in enumerate(ranked, 1):
        r["rank"] = rank
    return {**head, "start": p0, "end": p1, "period": p1, "base": p0, "threshold": threshold, "total": view_end,
            "n_significant": len(rows), "items": ranked[:limit], "falling": list(reversed(ranked))[:limit],
            "new": sorted((r for r in rows if r["is_new"]), key=lambda r: -r["value"])[:limit], **status}


# --------------------------------------------------------------------------- forecast
# The models, the backtest and the scenarios are in app/backend/forecasting (docs/forecasting.md);
# what follows reads the series, calls it and shapes the response.
def _forecast_pool() -> dict:
    """Every chapter of exports and imports against the world, monthly: the series the gradient
    boosting model of /forecast is trained on. Its own session: the pool is read once and cached."""
    from database import SessionLocal

    prod, flow_dim = DIMS["product"], DIMS["flow"]
    filters = {d: [v] for d, v in DEFAULTS.items() if d in DIMS and d not in (CONFIG["frequency_dimension"],
                                                                                 "product", "flow")}
    filters[CONFIG["frequency_dimension"]] = ["M"]
    params: dict = {"pool_total": prod["total_code"]}
    where = _where(filters, params) + [f'd."{prod["parent_column"]}" = :pool_total']
    sql = (f'SELECT o."{flow_dim["column"]}", o."{prod["column"]}", o."{TIME}", SUM({VALUE_EXPR}) FROM "{OBS}" o '
           f'JOIN "{prod["table"]}" d ON d.code = o."{prod["column"]}" WHERE {" AND ".join(where)} '
           f'GROUP BY o."{flow_dim["column"]}", o."{prod["column"]}", o."{TIME}" '
           f'ORDER BY o."{flow_dim["column"]}", o."{prod["column"]}", o."{TIME}"')
    out: dict[str, tuple[list, list]] = {}
    db = SessionLocal()
    try:
        for flow, code, period, value in db.execute(text(sql), params).fetchall():
            periods, values = out.setdefault(f"{flow}:{code}", ([], []))
            periods.append(period)
            values.append(float(value or 0))
    finally:
        db.close()
    return out


def _forecast_warm_up() -> None:
    """Fits the forecasts of exports and imports in the background when the backend starts, so the
    first request does not wait for the gradient boosting models (half a minute the very first
    time, then read from the disk cache). ``FORECAST_WARMUP=0`` turns it off; never under pytest."""
    import os
    import sys
    if os.environ.get("FORECAST_WARMUP", "1") == "0" or "pytest" in sys.modules:
        return

    def run() -> None:
        time.sleep(3)                                  # let the server start first
        try:
            import forecasting
            from database import SessionLocal
            forecasting.pool.ensure_loader(_forecast_pool)
            db = SessionLocal()
            try:
                for flow in ("EXPORT", "IMPORT"):
                    filters = {d: [v] for d, v in DEFAULTS.items() if d in DIMS}
                    filters.update({CONFIG["frequency_dimension"]: ["M"], "flow": [flow]})
                    rows, status = _series_rows(db, filters, None, None)
                    if not status["loaded"] or len(rows) < FORECAST_MIN_MONTHS:
                        continue
                    periods, values = forecasting.pool.consecutive([r["period"] for r in rows],
                                                                   [r["value"] for r in rows])
                    if len(values) >= FORECAST_MIN_MONTHS:
                        forecasting.forecast(values, periods, forecasting.DEFAULT, 12, 0.8)
            finally:
                db.close()
        except Exception:  # a warm-up only saves time; the request computes whatever is missing
            pass

    threading.Thread(target=run, name="forecast-warm-up", daemon=True).start()


def _forecast_years(periods: list[str], values, months: list[str], last: str, band) -> list[dict]:
    """Calendar years the forecast completes: the observed months of the year in progress plus the
    forecast of the rest. ``band(a, b, observed)`` gives (value, lo, hi) of months a..b ahead."""
    observed: dict[str, list[float]] = {}
    for p, v in zip(periods, values):
        observed.setdefault(p[:4], []).append(float(v))
    rows = []
    for year in sorted({p[:4] for p in months}):
        idx = [k for k, p in enumerate(months) if p.startswith(year)]
        seen = observed.get(year, []) if year == last[:4] else []
        if len(idx) + len(seen) != 12:
            continue                                  # a year the horizon does not complete
        base = sum(seen)
        v, a, b = band(idx[0] + 1, idx[-1] + 1, base)
        a, b = min(a, v), max(b, v)
        rows.append({"period": year, "value": v, "lo": a, "hi": b, "low": a, "high": b, "observed": base,
                     "observed_months": len(seen), "forecast_months": len(idx)})
    return rows


def _forecast_scenarios(db: Session, filters: dict, lo: Optional[str], hi: Optional[str], periods: list[str],
                        values, method: str, steps: int, months: list[str], annual: bool, horizon: int,
                        out: dict) -> list[dict]:
    """"The line stops" and "the line continues" for the known lines (forecasting.LINES) the series
    contains: the total of a flow (or the line's chapter itself), against the world."""
    import numpy as np
    import forecasting

    prod, partner = DIMS["product"], DIMS.get(FLOW_BY)
    product = (filters.get("product") or [DEFAULTS.get("product")])[0]
    if partner and (filters.get(FLOW_BY) or [partner["total_code"]])[0] != partner["total_code"]:
        return []                                      # chapters by month exist against the world only
    result = []
    for spec in forecasting.LINES:
        if product not in (prod["total_code"], spec["product"]) or spec["since"] not in periods:
            continue
        only = product == spec["product"]
        if only:
            line = np.asarray(values, float)
        else:
            rows, status = _series_rows(db, {**filters, "product": [spec["product"]]}, lo, hi)
            by_period = {r["period"]: r["value"] for r in rows}
            if not status["loaded"] or any(p not in by_period for p in periods):
                continue
            line = np.array([by_period[p] for p in periods], float)
        sc = forecasting.line_scenarios(values, line, periods, spec, method, steps, only_line=only)
        if sc is None:
            continue
        point = out["point"]
        for case in ("stops", "continues"):
            path = sc[case]
            if annual:
                def band(a, b, base, path=path):
                    v, l, h = out["sum_band"](a, b, 0.0)
                    s = float(path[a - 1:b].sum())
                    return base + s, base + s * (l / v if v else 1), base + s * (h / v if v else 1)
                rows = _forecast_years(periods, values, months, periods[-1], band)
            else:
                rows = []
                for k, p in enumerate(months[:horizon]):
                    v = float(path[k])
                    a = v * float(out["lo"][k] / point[k]) if point[k] else v
                    b = v * float(out["hi"][k] / point[k]) if point[k] else v
                    rows.append({"period": p, "value": v, "lo": a, "hi": b, "low": a, "high": b})
            result.append({"id": f"{sc['id']}_{case}", "line": sc["id"], "line_label": sc["label"], "case": case,
                           "label": sc[f"{case}_label"],
                           "since": sc["since"], "product": sc["product"], "cn": sc["cn"],
                           "recent_extra": sc["recent_extra"], "observed_extra": sc["observed_extra"], "rows": rows})
    return result


def _forecast_caveat(bt: Optional[dict], last: str, complete_until: Optional[str], prob: float,
                     scenarios: list[dict]) -> str:
    parts = []
    if bt and bt.get("coverage") is not None:
        parts.append(f"The band is where {prob:.0%} of the method's errors fell when it was tested on the past of this "
                     f"series (a conformal interval); tested that way, it held {bt['coverage']:.0%} of the actual "
                     "months.")
    else:
        parts.append(f"The band is where {prob:.0%} of the method's errors fell when it was tested on the past of this "
                     "series (a conformal interval).")
    parts.append("It does not cover breaks the past does not show, such as a new tariff or a lost customer.")
    if not bt or bt.get("mase_h12") is None or bt.get("naive_mase_h12") is None:
        parts.append("There is no backtest at 12 months: the series is too short.")
    elif bt["mase_h12"] >= bt["naive_mase_h12"]:
        parts.append(f"In a backtest over {bt['origins']} quarter ends it did not beat the seasonal naive forecast (the "
                     f"same month a year earlier) at 12 months ahead: a mean absolute percentage error of "
                     f"{bt['mape_h12']:.1%} against {bt['naive_mape_h12']:.1%}.")
        if (bt.get("skill_h3") or 0) > 0.005:
            parts.append(f"It did beat it at 3 months ahead, with errors {bt['skill_h3']:.0%} smaller.")
        parts.append("Read the band as a range of plausible values, not as a prediction.")
    else:
        parts.append(f"In a backtest over {bt['origins']} quarter ends it beat the seasonal naive forecast (the same "
                     f"month a year earlier) at 12 months ahead: a mean absolute percentage error of "
                     f"{bt['mape_h12']:.1%} against {bt['naive_mape_h12']:.1%}.")
    if scenarios:
        parts.append(f"Since {scenarios[0]['since']} a single product line, {scenarios[0]['line_label']}, adds trade "
                     "no model can foresee: the scenarios say what happens if it stops or continues.")
    if complete_until and last > complete_until:
        parts.append(f"Months after {complete_until} are provisional and are revised by the source.")
    parts.append("Values are nominal euros.")
    return " ".join(parts)


@router.get("/forecast")
def forecast(request: Request, horizon: int = 12, method: str = "auto", interval: Optional[float] = None,
             level: Optional[float] = None, start: Optional[str] = None, end: Optional[str] = None,
             adjust: bool = True, aggregate: Optional[str] = None, backtest: Optional[str] = None,
             db: Session = Depends(get_db)):
    """Forecast of the filtered series with an uncertainty band, from the monthly data.

    ``method``: ``auto`` (the default: ``ensemble``, the average of Holt-Winters exponential
    smoothing and gradient boosting trained on every HS2 chapter, the method that won the
    backtest, see docs/forecasting.md), or one of ``ensemble``, ``ets``, ``airline``, ``theta``,
    ``gbm``, ``stl_ets`` (the first version), ``snaive`` (the same month a year earlier) and, when
    torch is installed, ``nn`` (a neural network modelled in BESSER and generated as PyTorch code,
    see docs/forecasting_nn.md).
    The band is conformal: where ``interval`` (alias ``level``, 0.8 by default) of the method's
    errors fell in a rolling backtest on this very series. Deterministic: the same data gives the
    same answer.

    ``freq=M`` gives monthly rows. ``freq=A`` (the default) or ``aggregate=A`` gives calendar years:
    the year in progress is its observed months plus the forecast of the rest. ``rows`` is the
    history followed by the forecast, so ``rows.-1`` is the last forecast period; ``forecast`` has
    only the forecast (``lo``/``hi``, also as ``low``/``high``), ``reference`` the seasonal naive
    forecast. ``backtest`` holds the scores of the method (errors are fractions: 0.05 = 5%) and
    ``backtest.methods`` those of every method; ``backtest=2024`` names the year the annual
    backtest is run on (default: the last complete year), ``backtest=false`` leaves it out.
    ``scenarios`` (the total of a flow against the world, or chapter 85) says what happens if the
    smartphone line of September 2025 stops or continues. ``model_card`` says how the forecast was
    made for the page's "Model card": the members, the features, the training span, the backtest
    that chose the method (66 quarter ends) apart from this series' own (the last 20), the band and
    the limits (forecasting/card.py). ``adjust`` is accepted for symmetry with /series: the models
    handle the season themselves.
    """
    import numpy as np
    import forecasting
    from forecasting import pool as forecast_pool

    forecast_pool.ensure_loader(_forecast_pool)
    asked_method = method
    method = forecasting.resolve(method)
    if method not in forecasting.METHODS:
        raise HTTPException(400, f"Unknown method {asked_method!r}; use auto (the default) or one of "
                                 f"{sorted(forecasting.METHODS)}")
    if not 1 <= horizon <= 36:
        raise HTTPException(400, "horizon is a number of months from 1 to 36")
    prob = interval if interval is not None else (level if level is not None else 0.8)
    prob = prob / 100 if prob > 1 else prob
    if not 0.5 <= prob < 1:
        raise HTTPException(400, "interval is a coverage between 0.5 and 0.99 (0.8 = 80%)")
    if aggregate not in (None, "", "A", "M"):
        raise HTTPException(400, "aggregate is A (calendar years) or M (months)")
    freq_dim = CONFIG.get("frequency_dimension")
    tdim = CONFIG["time_dimension"]
    asked = request.query_params.get(freq_dim) if freq_dim else None
    asked = _normalise(DIMS[freq_dim], asked) if asked else DEFAULTS.get(freq_dim, "A")
    if asked not in ("A", "M"):
        raise HTTPException(400, f"{freq_dim} is M (monthly rows) or A (calendar years)")
    annual = aggregate == "A" or (not aggregate and asked == "A")
    filters = _filters(request, exclude={tdim, freq_dim}, db=db)
    filters[freq_dim] = ["M"]
    lo, hi = _month_bounds(start, end, "M")
    rows, status = _series_rows(db, filters, lo, hi)
    head = {"method": method, "method_label": forecasting.label(method), "freq": "A" if annual else "M",
            "level": prob, "interval": prob, "interval_method": "conformal"}
    if not status["loaded"]:
        return {**head, "horizon": 0, "history": [], "forecast": [], "rows": [], "reference": [], "backtest": None,
                "scenarios": [], "n_obs": 0,
                "caveat": "No data: the slice is not loaded and the source could not be reached.", **status}
    # the longest run of consecutive months up to the last one
    run = rows[-1:]
    for r in reversed(rows[:-1]):
        if _month_add(r["period"], 1) != run[0]["period"]:
            break
        run.insert(0, r)
    if len(run) < FORECAST_MIN_MONTHS:
        raise HTTPException(400, f"A forecast needs at least {FORECAST_MIN_MONTHS} consecutive months; "
                                 f"this slice has {len(run)}")
    periods = [r["period"] for r in run]
    values = np.array([r["value"] for r in run], float)
    last = periods[-1]
    test_year = None if backtest in (None, "", "true", "1", "false", "0", "no", "off") else backtest
    show_backtest = backtest not in ("false", "0", "no", "off")
    key = (tuple(sorted((k, tuple(v)) for k, v in filters.items())), lo, hi, horizon, prob, annual, test_year,
           show_backtest, method, last, hash(values.tobytes()))
    if key in _FORECAST_CACHE:
        return {**_FORECAST_CACHE[key], **status}

    observed_in_year = int(last[5:7]) % 12          # months of the year in progress already observed
    to_year_end = 12 - observed_in_year if observed_in_year else 12
    steps = max(horizon, to_year_end) if annual else horizon
    try:
        out = forecasting.forecast(values, periods, method, steps, prob, test_year=test_year)
    except forecasting.NotEnoughHistory as exc:   # a line too young for a tested forecast: say so (422), never 500
        raise HTTPException(422, str(exc))
    point, low, high = out["point"], out["lo"], out["hi"]
    months = [_month_add(last, k + 1) for k in range(steps)]
    naive: list[float] = []
    for k in range(steps):
        naive.append(float(values[len(values) - 12 + k]) if k < 12 else naive[k - 12])
    monthly = []
    for k, p in enumerate(months):
        v = float(point[k])
        a, b = min(float(low[k]), v), max(float(high[k]), v)
        monthly.append({"period": p, "value": v, "lo": a, "hi": b, "low": a, "high": b})

    if annual:
        observed: dict[str, list[float]] = {}
        for p, v in zip(periods, values):
            observed.setdefault(p[:4], []).append(float(v))
        history = [{"period": y, "value": sum(vs)} for y, vs in sorted(observed.items()) if len(vs) == 12]
        fc = _forecast_years(periods, values, months, last, out["sum_band"])
        ref = []
        for row in fc:
            idx = [k for k, p in enumerate(months) if p.startswith(row["period"])]
            ref.append({"period": row["period"], "value": row["observed"] + sum(naive[k] for k in idx)})
    else:
        history = [{"period": p, "value": float(v)} for p, v in zip(periods, values)]
        fc = monthly[:horizon]
        ref = [{"period": p, "value": v} for p, v in zip(months, naive)][:horizon]
    scenarios = _forecast_scenarios(db, filters, lo, hi, periods, values, method, steps, months, annual, horizon, out)
    bt = out["backtest"] if show_backtest else None
    complete_until = meta(db).get("complete_until")
    result = {
        **head, "horizon": len(fc), "last_observed": last, "n_obs": len(values), "log": out["log"],
        "history": history, "forecast": fc, "rows": history + fc, "monthly": monthly, "reference": ref,
        "backtest": bt, "scenarios": scenarios,
        "caveat": _forecast_caveat(out["backtest"], last, complete_until, prob, scenarios),
        "model_card": forecasting.card.build(method, out["backtest"], periods, prob, scenarios, complete_until),
    }
    if len(_FORECAST_CACHE) > 64:
        _FORECAST_CACHE.clear()
    _FORECAST_CACHE[key] = result
    return {**result, **status}


_forecast_warm_up()


# --------------------------------------------------------------------------- events
def _events() -> list[dict]:
    if not _EVENTS_CACHE:
        _EVENTS_CACHE.append(json.loads(EVENTS_PATH.read_text(encoding="utf-8")))
    return _EVENTS_CACHE[0]


def _date_bound(value: Optional[str], upper: bool, name: str) -> Optional[str]:
    """A period or date as an ISO date: 2020 -> 2020-01-01 (or 2020-12-31 as an upper bound)."""
    if not value:
        return None
    if re.fullmatch(r"\d{4}", value):
        return f"{value}-12-31" if upper else f"{value}-01-01"
    if re.fullmatch(r"\d{4}-(0[1-9]|1[0-2])", value):
        return f"{value}-31" if upper else f"{value}-01"
    if re.fullmatch(r"\d{4}-\d{2}-\d{2}", value):
        return value
    raise HTTPException(400, f"{name} is a year (2020), a month (2020-03) or a date (2020-03-11), not {value!r}")


def _codes(raw: Optional[str]) -> set[str]:
    return {v.strip() for v in (raw or "").split(",") if v.strip()}


@router.get("/events")
def events(start: Optional[str] = None, end: Optional[str] = None,
           from_: Optional[str] = Query(None, alias="from"), to: Optional[str] = None,
           category: Optional[str] = None, kind: Optional[str] = None, partner: Optional[str] = None,
           product: Optional[str] = None, flow: Optional[str] = None, limit: int = 50):
    """Dated events that can move trade: agreements, tariffs, sanctions, wars, the pandemic...

    A curated list (events.json), every row with its source. ``start``/``end`` (aliases
    ``from``/``to``) keep the events that overlap the window; ``category`` (alias ``kind``), a
    comma-separated list of agreement, dispute, tariff, sanction, war, disaster, pandemic, policy,
    shock. ``partner``, ``product`` (its HS chapter is matched) and ``flow`` keep the events scoped
    to them plus the events that concern all trade. ``at``/``until`` are months, ready for an event
    mark; ``date``/``end_date`` the exact dates.
    """
    lo = _date_bound(start or from_, False, "start")
    hi = _date_bound(end or to, True, "end")
    kinds = _codes(category) | _codes(kind)
    unknown = kinds - EVENT_KINDS
    if unknown:
        raise HTTPException(400, f"Unknown category {sorted(unknown)}; known: {sorted(EVENT_KINDS)}")
    partners = _codes(partner) - {DIMS["partner"]["total_code"]}
    chapters = {c[:2] for c in _codes(product) if c[:2].isdigit()}
    flows = {DIMS["flow"]["literals"].get(f, f) for f in _codes(flow)}
    out = []
    for ev in sorted(_events(), key=lambda e: e["date"]):
        until = ev.get("end_date") or ev["date"]
        if (lo and until < lo) or (hi and ev["date"] > hi) or (kinds and ev["kind"] not in kinds):
            continue
        scope = ev.get("scope") or {}
        if partners and scope.get("partners") and not partners & set(scope["partners"]):
            continue
        if chapters and scope.get("products") and not chapters & set(scope["products"]):
            continue
        if flows and scope.get("flows") and not flows & set(scope["flows"]):
            continue
        out.append({"id": ev["id"], "at": ev["date"][:7], "until": ev["end_date"][:7] if ev.get("end_date") else None,
                    "label": ev.get("label") or ev["title"], "category": ev["kind"], "title": ev["title"],
                    "date": ev["date"], "end_date": ev.get("end_date"), "kind": ev["kind"], "scope": scope,
                    "description": ev.get("description", ""), "source": ev["source_url"],
                    "source_url": ev["source_url"], "confidence": ev.get("confidence", "curated")})
    return out[:limit]


# --------------------------------------------------------------------------- flows
def _with_query(request: Request, **params) -> Request:
    """The same request with some query parameters replaced (for calling another endpoint's logic)."""
    items = [(k, v) for k, v in request.query_params.multi_items() if k not in params]
    items += [(k, str(v)) for k, v in params.items() if v is not None]
    return Request({**request.scope, "query_string": urlencode(items).encode("latin-1")})


@router.get("/flows")
def flows(request: Request, period: str, previous: Optional[str] = None, max_items: int = 8,
          threshold: Optional[float] = None, db: Session = Depends(get_db)):
    """The crossroads in one call: imports by partner (``in``), exports by partner (``out``) and the
    balance, for a Sankey of partners -> Luxembourg -> partners. Each side is /ranking by partner
    (items, other, total, unallocated); ``partner_counts`` counts every partner with trade. With
    ``previous``, items carry ``previous`` and ``change``, and each side its ``previous_total``."""
    by = _dim(FLOW_BY)
    tdim = CONFIG["time_dimension"]
    sides: dict[str, dict] = {}
    statuses = []
    for key, flow in (("in", "IMPORT"), ("out", "EXPORT")):
        req = _with_query(request, flow=flow)
        r = _ranking(db, req, FLOW_BY, period, None, None, threshold, max_items, "total")
        statuses.append(r)
        side = {"flow": flow, "total": r["total"], "items": r["items"], "other": r.get("other"),
                "unallocated": r.get("unallocated"), "coverage": r.get("coverage"), "threshold": r.get("threshold"),
                "n_partners": len(r["items"]) + ((r.get("other") or {}).get("count") or 0)}
        if previous and r["loaded"]:
            f = _filters(req, exclude={FLOW_BY, tdim}, db=db)
            f[tdim] = [previous]
            before = _grouped(db, by, f, None, None)
            needed, extra = _needed(db, f, by)
            st = _ensure(db, needed, extra, previous, previous, probe=lambda: bool(before))
            if st["fetched_live"]:
                before = _grouped(db, by, f, None, None)
            statuses.append(st)
            total = by.get("total_code")
            side["previous_total"] = (_value_of(db, by, total, f) if total else None) or \
                sum(v for c, v in before.items() if _is_member(by, c, db))
            for item in side["items"]:
                item["previous"] = before.get(item["code"], 0.0)
                item["change"] = item["value"] - item["previous"]
        sides[key] = side
    loaded = all(s.get("loaded", True) for s in statuses)
    t_in, t_out = sides["in"]["total"], sides["out"]["total"]
    out = {"period": period, "previous": previous, "by": FLOW_BY, "in": sides["in"], "out": sides["out"],
           "balance": (t_out - t_in) if loaded and t_in is not None and t_out is not None else None,
           "partner_counts": {"in": sides["in"]["n_partners"], "out": sides["out"]["n_partners"]},
           "loaded": loaded, "fetched_live": any(s.get("fetched_live") for s in statuses)}
    if previous and loaded:
        out["previous_balance"] = sides["out"].get("previous_total", 0) - sides["in"].get("previous_total", 0)
    return out


# --------------------------------------------------------------------------- matrix (contract 1.1)
MATRIX_MEASURES = {"value", "share", "rank", "growth"}


def _matrix_data(db: Session, by: dict, filters: dict, level: Optional[int], parent: Optional[str],
                 total_code: Optional[str], lo: str, hi: str) -> dict[str, dict[str, float]]:
    """{code: {period: value}} of the members of ``by`` and of ``total_code``, in one GROUP BY."""
    params: dict = {"p_start": lo, "p_end": hi}
    where = _where(filters, params) + [f'o."{TIME}" >= :p_start', f'o."{TIME}" <= :p_end']
    join = ""
    if by.get("hierarchy"):
        join = f'JOIN "{by["table"]}" d ON d.code = o."{by["column"]}"'
        member = []
        if level is not None:
            member.append("d.level = :lvl")
            params["lvl"] = level
        if parent:
            member.append(f'd."{by["parent_column"]}" = :parent')
            params["parent"] = parent
        if member:
            cond = " AND ".join(member)
            if total_code:
                cond = f'({cond}) OR o."{by["column"]}" = :total_code'
                params["total_code"] = total_code
            where.append(f"({cond})")
    sql = (f'SELECT o."{by["column"]}", o."{TIME}", SUM({VALUE_EXPR}) FROM "{OBS}" o {join} '
           f'WHERE {" AND ".join(where)} GROUP BY o."{by["column"]}", o."{TIME}"')
    out: dict[str, dict[str, float]] = {}
    for code, period, value in db.execute(text(sql), params).fetchall():
        out.setdefault(code, {})[period] = float(value or 0)
    return out


@router.get("/matrix")
def matrix(request: Request, by: str, start: str, end: str, level: Optional[int] = None,
           parent: Optional[str] = None, max_items: int = 12, measure: str = "value",
           threshold: Optional[float] = None, db: Session = Depends(get_db)):
    """The members of ``by`` (rows) by period (columns) from ``start`` to ``end``: a heatmap of
    codes by years, or the ranks of a bump chart.

    ``periods`` lists every period of the frequency (``freq``, annual by default) in the span;
    ``rows[i].values[j]`` belongs to ``periods[j]`` and is ``null`` where there is no data. The rows
    are the ``max_items`` largest members over the span (by their summed value), largest first,
    among those above the significance ladder in at least one period (their share of the period's
    total, or ``threshold``). ``measure``: ``value`` (euros), ``share`` (a fraction of the period's
    total: the dimension's total, or ``parent`` when drilling), ``rank`` (1-based, among every
    member with trade in that period) or ``growth`` (a fraction, on the previous period). Each row
    also has ``total`` (its value summed over the span); ``totals`` are the periods' totals.
    """
    if measure not in MATRIX_MEASURES:
        raise HTTPException(400, f"measure is one of {sorted(MATRIX_MEASURES)}, not {measure!r}")
    if not 1 <= max_items <= 100:
        raise HTTPException(400, "max_items is between 1 and 100")
    dim = _dim(by)
    tdim = CONFIG["time_dimension"]
    filters = _filters(request, exclude={by, tdim}, db=db)
    if parent:
        _check(db, dim, [parent])
    level = _drill_level(db, dim, level, parent)
    freq = _freq_of(filters)
    lo, hi = _month_bounds(start, end, freq)
    if lo > hi:
        raise HTTPException(400, f"start ({start}) must not be after end ({end})")
    total_code = parent or dim.get("total_code")

    def query() -> dict:
        return _matrix_data(db, dim, filters, level, parent, total_code, lo, hi)

    data = query()
    needed, extra = _needed(db, filters, dim, parent, level)
    status = _ensure(db, needed, extra, lo, hi,
                     probe=lambda: any(c != total_code for c in data))
    if status["fetched_live"]:
        data = query()
    known = meta(db)["periods"]
    span = known.get(freq, []) if CONFIG.get("frequency_dimension") else known.get("all", [])
    periods = [p for p in span if lo <= p <= hi and len(p) == len(lo)] or \
        sorted({p for s in data.values() for p in s})
    head = {"by": by, "measure": measure, "start": start, "end": end, "freq": freq, "level": level,
            "parent": parent, "periods": periods}
    if not status["loaded"]:
        return {**head, "threshold": threshold, "rows": [], "totals": [], **status}
    total_series = data.pop(total_code, None) if total_code else None
    members = {c: s for c, s in data.items() if _in_view(dim, c, db, parent)}
    totals = {p: (total_series.get(p) if total_series and total_series.get(p) else
                  sum(s.get(p, 0.0) for s in members.values())) for p in periods}
    threshold = _default_threshold(dim, level) if threshold is None else threshold
    significant = [c for c, s in members.items()
                   if any(totals.get(p) and v / totals[p] >= threshold for p, v in s.items() if p in totals)]
    chosen = sorted(significant, key=lambda c: -sum(members[c].get(p, 0.0) for p in periods))[:max_items]
    ranks: dict[str, dict[str, int]] = {}
    if measure == "rank":
        for p in periods:
            order = sorted((c for c, s in members.items() if s.get(p, 0.0) > 0), key=lambda c: -members[c][p])
            ranks[p] = {c: i for i, c in enumerate(order, 1)}
    labels = _labels(db, dim, chosen)
    rows = []
    for c in chosen:
        s = members[c]
        raw = [s.get(p) for p in periods]
        if measure == "value":
            values = raw
        elif measure == "share":
            values = [v / totals[p] if v is not None and totals.get(p) else None for v, p in zip(raw, periods)]
        elif measure == "rank":
            values = [ranks[p].get(c) for p in periods]
        else:
            values = [None] + [(b / a - 1) if a and b is not None and a > 0 else None for a, b in zip(raw, raw[1:])]
            values = values[:len(periods)]
        rows.append({"code": c, "name": labels[c], "values": values,
                     "total": sum(v for v in raw if v is not None)})
    return {**head, "threshold": threshold, "n_significant": len(significant), "rows": rows,
            "totals": [totals.get(p) for p in periods], **status}


# --------------------------------------------------------------------------- tree (contract 1.1)
TREE_MAX_LEVEL = 4    # CN8; a tree from the total goes to HS6 at most (depth 3)


@router.get("/tree")
def tree(request: Request, period: str, by: str = "product", depth: int = 2, threshold: str = "auto",
         db: Session = Depends(get_db)):
    """The goods as nested tiles: HS2 chapters, their HS4 headings, their HS6 subheadings.

    ``depth`` (1 to 3) is how many levels below the root are listed. The root is the total, or the
    code given as ``product`` (``product=85`` lists the headings of chapter 85). ``share`` is a
    fraction of ``total`` (the root's value). Children below the threshold go into one ``OTHER``
    child, which also holds what the listed children do not account for, so a node's children add up
    to its value. ``threshold=auto`` follows the significance ladder (1% of the total for the first
    level below the root, 0.1% for the second, 0.01% for the third); a number (0.02) applies to every
    level. Levels that are not in the database for this selection are left out rather than fetched
    (``depth`` then says how many levels the tree has, ``requested_depth`` what was asked).
    """
    dim = _dim(by)
    if not dim.get("hierarchy") or dim.get("role") == "geo":
        raise HTTPException(400, f"A tree is by a nomenclature (by=product), not by {by!r}")
    if not 1 <= depth <= 3:
        raise HTTPException(400, "depth is 1, 2 or 3")
    if threshold == "auto":
        fixed: Optional[float] = None
    else:
        try:
            fixed = float(threshold)
        except ValueError:
            raise HTTPException(400, f"threshold is auto or a share between 0 and 1, not {threshold!r}")
        if not 0 <= fixed < 1:
            raise HTTPException(400, f"threshold is auto or a share between 0 and 1, not {threshold!r}")
    tdim = CONFIG["time_dimension"]
    filters = _filters(request, exclude={by}, db=db)
    filters[tdim] = [period]
    asked = [_normalise(dim, v) for v in (request.query_params.get(by) or "").split(",") if v]
    if len(asked) > 1:
        raise HTTPException(400, f"A tree has one root; give one {by} code, not {asked}")
    root = asked[0] if asked else dim.get("total_code")
    if not root:
        raise HTTPException(400, f"Give the root as {by}=<code>")
    root_level = _level_of(db, dim, root)
    top = min(root_level + depth, TREE_MAX_LEVEL)
    if top <= root_level:
        raise HTTPException(400, f"{root} has no level below it")
    prefix = "" if root == dim.get("total_code") else root

    def codes_at(lvl: int) -> set:
        rows_ = db.execute(text(f'SELECT code FROM "{dim["table"]}" WHERE level = :l AND code LIKE :p'),
                           {"l": lvl, "p": prefix + "%"}).fetchall()
        return {r[0] for r in rows_}

    def query(deepest: int) -> list:
        params: dict = {"lo": root_level, "hi": deepest, "p": prefix + "%"}
        where = _where(filters, params) + ["d.level BETWEEN :lo AND :hi", f'o."{dim["column"]}" LIKE :p']
        sql = (f'SELECT o."{dim["column"]}", d."{dim["parent_column"]}", d.level, SUM({VALUE_EXPR}) '
               f'FROM "{OBS}" o JOIN "{dim["table"]}" d ON d.code = o."{dim["column"]}" '
               f'WHERE {" AND ".join(where)} GROUP BY o."{dim["column"]}", d."{dim["parent_column"]}", d.level')
        return db.execute(text(sql), params).fetchall()

    # The deepest level the database holds for this selection; only the first level is fetched live.
    deepest = root_level + 1
    base_needed = {d: v for d, v in _needed(db, filters)[0].items() if d != by}
    for lvl in range(top, root_level + 1, -1):
        needed = {**base_needed, by: ("any_of", codes_at(lvl))}
        covered = _covered(db, needed, period, period)
        if covered is None:  # no registry: whatever is in the database counts as loaded
            covered = any(r[2] == lvl for r in query(lvl))
        if covered:
            deepest = lvl
            break
    rows = query(deepest)
    first = {**base_needed, by: ("any_of", codes_at(root_level + 1) or {root})}
    status = _ensure(db, first, {by: {root}}, period, period, probe=lambda: any(r[2] == root_level + 1 for r in rows))
    if status["fetched_live"]:
        rows = query(deepest)
    head = {"by": by, "period": period, "root": root, "depth": deepest - root_level, "requested_depth": depth,
            "threshold": threshold}
    if not status["loaded"]:
        return {**head, "total": None, "children": [], **status}
    value = {c: float(v or 0) for c, _, _, v in rows}
    kids: dict[str, list[str]] = {}
    for c, parent_code, lvl, v in rows:
        if lvl > root_level and v and v > 0:
            kids.setdefault(parent_code, []).append(c)
    total = value.get(root) or sum(value[c] for c in kids.get(root, []))
    if not total:
        return {**head, "total": 0, "children": [], **status}
    labels = _labels(db, dim, [c for cs in kids.values() for c in cs])

    def node_children(code: str, below: int) -> list[dict]:
        listed = sorted(kids.get(code, []), key=lambda c: -value[c])
        if not listed:
            return []
        cut = _default_threshold(dim, below) if fixed is None else fixed
        kept = [c for c in listed if value[c] / total >= cut]
        out = [{"code": c, "name": labels[c], "value": value[c], "share": value[c] / total,
                "children": node_children(c, below + 1)} for c in kept]
        hidden = len(listed) - len(kept)
        own = value.get(code) or sum(value[c] for c in listed)
        rest = own - sum(value[c] for c in kept)
        # small children, plus what no listed child accounts for (confidential or unallocated trade)
        if rest > 0 and (hidden or rest > 0.005 * own):
            out.append({"code": "OTHER", "name": f"Other ({hidden})" if hidden else "Not allocated",
                        "value": rest, "share": rest / total, "count": hidden, "children": []})
        return out

    return {**head, "total": total, "children": node_children(root, 1), **status}


