_NO_FILTERS = {"/insights/meta", "/insights/events", "/product/search/"}


@router.get("/methods")
def methods(endpoint: Optional[str] = None):
    """The method catalogue: for each endpoint the page and the agents use, its plain name, one everyday
    sentence, the technical detail for statisticians, its inputs and what it returns. ``variants`` change the
    name when a parameter changes the method (``adjust=true`` on /insights/series is a seasonal adjustment).
    ``endpoint`` returns that one entry."""
    entries = [{"endpoint": e, **m, "filters": {} if e in _NO_FILTERS else _FILTERS} for e, m in METHODS.items()]
    if endpoint is not None:
        hit = [m for m in entries if m["endpoint"] == endpoint]
        if not hit:
            raise HTTPException(404, f"no method for {endpoint!r}; known: {', '.join(METHODS)}")
        return hit[0]
    return {"source": "Eurostat ds-045409 (official, produced with STATEC)", "count": len(entries),
            "methods": entries}
